programs.sol:
"""A weak, local spelling-boundary approximation.

Short, space-prefixed vowel beginnings get negative offsets after isolated
vowel-free Latin/Cyrillic letter fragments. Single vowel-free beginnings get
the opposite offset there. Formatting markers have separate learned offsets.
Only the previous token is retained; document changes discard it. Most
individual-token variation is deliberately not represented by this model.
"""
READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюя')
ALPHABET = frozenset(
    'abcdefghijklmnopqrstuvwxyzабвгдеёжзийклмнопрстуфхцчшщъыьэюя'
)
FUNCTION_WORDS = frozenset('''
a an the of to in on at for from with by as into over under after before
between through without about and or but if while because although than
whether nor yet so not no never am is are was were be been have has had do
does did will would can could should may might must i me my you your he
him his she her it its we us our they them their who this that these those
de du del en em por para con da di do dos das
'''.split())


def shape(text):
    word = text.strip().lower()
    letters = bool(word) and all(c in ALPHABET for c in word)
    vowel = letters and word[0] in VOWELS
    consonants = letters and not any(c in VOWELS for c in word)
    return word, letters, vowel, consonants


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    text = prefix.token_strings[-1]
    word, letters, vowel, consonants = shape(text)
    prior, prior_letters, _, prior_consonants = shape(previous)
    boundary = text[:1].isspace()
    short_cluster = prior_consonants and len(prior) <= 2
    prior_vowels = prior_letters and all(c in VOWELS for c in prior)
    value = -0.0002

    if boundary and vowel and len(word) <= 4:
        value += 0.002
        if prior_consonants and len(prior) == 1:
            value -= 0.058
        elif prior_consonants and len(prior) == 2:
            value -= 0.034
        if short_cluster and word not in FUNCTION_WORDS:
            value -= 0.025
        if prior_vowels:
            value += 0.007
        if reset:
            value -= 0.020
    if boundary and consonants:
        if len(word) == 1 and short_cluster:
            value += 0.031
        if len(word) <= 2 and prior_vowels:
            value -= 0.015
        if len(word) == 1 and reset:
            value += 0.095
    if consonants and len(word) >= 4:
        value -= 0.038
    if letters and not boundary and len(word) >= 4:
        if prior_consonants and len(prior) == 1:
            value += 0.004

    if text.startswith('.') and '\n' in text:
        value -= 0.012
    if text == '://':
        value += 0.078
    if text == ' |':
        value += 0.048
    if word == '|' and any(c.isalpha() for c in previous):
        value += 0.025
    if text.startswith('<|'):
        value += 0.032
    if '·' in text:
        value += 0.058
    if text == '\f':
        value += 0.225
    return (doc, text), float(value)

programs.luna:
"""Flag selected formal, legal, and administrative vocabulary associated with the feature."""
READS = ()

FORMAL_WORDS = {
    "ownership", "holder", "entity", "interstate", "thereof",
    "pursuant", "offense", "persons", "performance", "such",
    "may", "right",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, 0.35 if word in FORMAL_WORDS else 0.0

"""Approximate a sparse discourse cue in the MLP output.

It is strongest on reporting speech (especially 'said' and 'says'), and also
marks a few other reporting words and discourse connectors. Quotation-ending
punctuation makes the speech-attribution prediction stronger. Unrecognized
contexts are assigned zero; this captures the readable lexical pattern, not
all context-dependent activations.
"""
READS = ()

REPORTERS = {
    "said": 1.35,
    "says": 1.25,
    "told": 1.1,
    "tells": 0.85,
    "announced": 0.75,
    "explains": 0.8,
    "replied": 1.0,
    "wrote": 0.4,
    "noted": 0.35,
    "added": 0.17,
    "asked": 0.1,
    "according": 0.35,
    "say": -0.5,
    "tell": -0.3,
    "dijo": 1.0,
    "说": 0.45,
    "说道": 0.9,
    "道": 0.3,
    "いう": 0.8,
}

CONNECTORS = {"though": 0.36, "too": 0.19}
CLOSING_QUOTES = ("”", "\"", "»", "」", "』", "〉")


def _word(token):
    return token.strip().strip(" \t\r\n.,!?;:()[]{}\"'“”‘’<>，。！？；：、").casefold()


def _quoted_before(prefix):
    end = len(prefix.token_strings) - 1
    if end == 0:
        return False
    document = prefix.document_ids[-1]
    start = max(0, end - 12)
    while start < end and prefix.document_ids[start] != document:
        start += 1
    recent = "".join(prefix.token_strings[start:end])
    quote_at = max((recent.rfind(mark) for mark in CLOSING_QUOTES), default=-1)
    if quote_at < 0:
        return False
    after_quote = recent[quote_at + 1:].strip(" ,\t\r\n")
    return len(after_quote) <= 24 and not any(c in after_quote for c in ".!?\n")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    quoted = _quoted_before(prefix)
    if word == "said" and quoted:
        return None, 3.5
    if word == "says" and quoted:
        return None, 4.8
    if word == "according" and quoted:
        return None, 1.25
    if word in REPORTERS:
        return None, float(REPORTERS[word])
    if word in CONNECTORS:
        return None, float(CONNECTORS[word])

    if word == "to" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = _word(prefix.token_strings[-2])
            if previous == "according":
                return None, 0.8
    return None, 0.0

programs.sol:
"""Sparse, local approximation of a weak first-layer component.

Tool-closing tags and the following turn-end have opposite signs. A few spatial,
temporal and degree-word classes also have reproducible mean responses. These
rules deliberately ignore most irregular token-specific variation; they are
not a complete semantic interpretation of the component.
"""
READS = ()

# A shared response per familiar word class, not a token-ID lookup table.
WORD_CLASSES = (
    (0.094, 'almost nearly completely entirely totally enough'),  # extent boundary
    (-0.049, 'rather pretty somewhat quite'),                    # qualified degree
    (0.051, 'left right leftward rightward'),                    # horizontal direction
    (0.031, 'up above upward upwards'),                          # upward direction
    (0.035, 'out outside outward outwards'),                     # outward direction
    (-0.040, 'top bottom'),                                      # vertical extrema
    (0.026, 'now current today currently present'),               # present time
    (0.035, 'then next after afterward afterwards subsequently'), # sequence
    (0.035, 'time times moment moments instant duration period interval era'),
    (-0.014, 'more less'),                                       # quantity comparison
    (-0.008, 'can could may might must should shall will would'), # modal verbs
)
WORD_CLASSES = tuple((value, frozenset(words.split()))
                     for value, words in WORD_CLASSES)
CARDINALS = frozenset('one two three four five six seven eight nine ten'.split())
PROPORTIONS = frozenset(('percent', 'percentage', 'proportion', '%'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip().lower()
    value = 0.0011

    if token == '</tool_response>':
        value = 0.121
    elif token == '<tool_call>':
        value = -0.056
    elif token == '</tool_call>':
        value = 0.020
    elif token == '<|im_start|>':
        value = -0.0215 if first else 0.0252
    elif token == '<|im_end|>':
        if previous in ('</tool_response>', '</tool_call>'):
            value = -0.1565
        elif previous.rstrip().endswith(('.', '?', '!')):
            value = 0.0428
        else:
            value = -0.0158
    elif token == '<|endoftext|>' and first:
        value = 0.300
    elif first and token == '#':
        value = -0.2764
    elif token == '\r':
        value = 0.099
    elif token == '.\n\n':
        value = -0.0103
    elif word == '://':
        value = 0.066
    elif word == '[]':
        value = 0.082
    elif word and set(word) == {'_'}:
        value = -0.0235 if len(word) == 1 else -0.0146
    elif word == '–':
        value = 0.022
    elif word == '—':
        value = -0.016
    elif word == 'these':  # proximal plural demonstrative
        value = -0.066
    elif word == 'of' and prev in PROPORTIONS:
        value = 0.100
    elif word == 'of' and prev in CARDINALS:
        value = 0.058
    elif word == 'time' and prev == 'same':
        value = 0.110
    else:
        for response, words in WORD_CLASSES:
            if word in words:
                value = response
                break
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP neuron 2566 of down_proj: fires on the word right after an indefinite
article ("a", "an"), with its strength set by which word it is."""
READS = ()

ARTICLES = {"a", "an"}
# Pin-pointing words: "a particular / specific / single / certain ..."
POINTING = {"particular", "specific", "single", "certain"}
# Newness, kind and fresh-quality adjectives: "a new / different / very / simple ..."
KIND_ADJ = {"new", "different", "very", "recent", "newly", "simple", "common", "separate", "similar",
            "possible", "typical", "popular", "special", "rare", "unusual", "famous", "particularly"}
# Other everyday adjectives: "a good / large / small / long ..."
PLAIN_ADJ = {"good", "large", "small", "long", "big", "great", "high", "short", "low", "major",
             "significant", "important", "quick", "useful", "young", "valid", "difficult", "nice",
             "old", "pretty", "interesting", "strange", "beautiful", "simpler", "easy", "clear"}
# Counts, ordinals and quantity-measure words: "a total / maximum / first / two ..."
NUMBERS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "first",
           "second", "third", "fourth", "fifth", "last", "next", "final", "total", "maximum", "minimum",
           "average", "number", "max", "min", "half", "median"}
KIND_NOUNS = {"type", "types", "species", "kind", "kinds", "sort", "example", "group", "groups",
              "genus", "copy", "pair", "couple", "series", "piece", "lot"}
QUANT_WORDS = {"minimum", "maximum", "total", "any", "each", "all", "range", "variety", "majority",
               "many", "none"}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    before = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    if word == "of":  # "a type of", "any of": the same idea one word later
        if before in KIND_NOUNS:
            return None, 0.4
        if before in QUANT_WORDS:
            return None, -0.3
        return None, 0.0
    if before not in ARTICLES or not word.isalpha():
        return None, 0.0
    if word in POINTING:
        return None, 3.3
    if word in KIND_ADJ:
        return None, 1.9
    if word in PLAIN_ADJ:
        return None, 1.0
    if word in NUMBERS:
        return None, -1.2
    return None, 0.1

