"""Approximate a sparse response to words that qualify or narrow a noun.

The harvest examples often put the response on modifiers such as “new,”
“single,” and “particular.” This lexical rule is a rough cue, not a POS tagger.
"""
READS = ()

QUALIFIERS = {
    "new", "single", "particular", "other", "such", "specific",
    "small", "popular", "typical", "special", "unique", "different",
    "common", "known", "separate", "appropriate", "analogous", "quick",
    "timely", "high", "better", "wide", "specialised", "specialized",
    "very", "relatively", "pretty", "curious", "complex", "valuable",
}
DETERMINERS = {
    "a", "an", "the", "this", "that", "these", "those", "each",
    "every", "any", "some", "one", "three", "another", "its",
}
ADJECTIVE_ENDINGS = (
    "al", "ar", "ate", "ed", "ent", "ful", "ible", "ic", "ical",
    "ive", "less", "ous", "ized", "ised",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    before = prefix.token_strings[-2].strip().lower() if same_document else ""

    if word in {"total", "default", "bottom"}:
        return None, -0.22
    if word in {"new", "single", "particular"}:
        return None, 0.48
    if word in QUALIFIERS:
        return None, 0.20
    if before in DETERMINERS and word.endswith(ADJECTIVE_ENDINGS):
        return None, 0.12
    return None, 0.0

programs.haiku:
"""Indefinite article after a preposition: "in a", "of an", "from a", "for some".

Component layers.0.mlp.down_proj:2567 reads an indefinite article or quantifier and looks at
the word just before it. After a preposition of place or time ("in a", "on an", "from a",
"across a") it fires strongly. After "of", "to", "for", "by" it fires a bit less, and after
"with" less again. After a copula, negation, conjunction or punctuation ("is a", "not a",
"as a", "and a", ", a") it stays near zero. Any other word gives a middle value, mostly verbs
that take an object. So it is roughly "this article starts the object of a preposition or
verb". "The", "this" and "that" do not fire it.
"""

READS = ()

# Indefinite articles, and how strongly each one fires relative to English "a".
ARTICLES = {" a": 1.2, " an": 1.2}
# Other indefinite determiners, quantifiers and foreign articles fire more weakly.
OTHER_INDEFINITES = {" some", " any", " another", " one", " two", " three", " four", " several",
                     " many", " multiple", " various", " certain", " someone", " something",
                     " una", " un", " une", " uma", " eine", " einen", " einer", " einem"}

# The word before, lowercased without its leading space.
LOCATION = {"in", "on", "at", "from", "over", "into", "during", "under", "through", "across",
            "against", "towards", "toward", "within", "inside", "around", "behind", "upon",
            "via", "about", "between"}
OTHER_PREPOSITIONS = {"of", "to", "for", "by", "using", "use", "uses", "choose"}
NOT_OBJECT = {"is", "was", "be", "been", "are", "were", "as", "and", "or", "has", "have", "had",
              "not", "also", "just", "such", "make", "create", "like", "without", "than", "'s"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if token in ARTICLES:
        strength = ARTICLES[token]
    elif token in OTHER_INDEFINITES:
        strength = 0.6
    else:
        return None, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if before in LOCATION:
        gate = 3.5
    elif before in OTHER_PREPOSITIONS:
        gate = 2.5
    elif before == "with":
        gate = 1.6
    elif before in NOT_OBJECT or not before.isalpha():
        gate = 0.0
    else:
        gate = 0.8
    return None, strength * gate

programs.luna:
"""Estimate activations on conversation and tool-format markers.

Marker responses in the sampled text were positive and comparatively large;
ordinary text is left at zero.  Different boundary roles get different sizes.
"""

READS = ()

TOOL_MARKERS = {
    "<tool_response>": 0.95,
    "</tool_response>": 0.50,
    "</tool_call>": 0.64,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "<|im_end|>":
        return None, 1.75
    if token == "<|im_start|>":
        return None, 1.05
    return None, TOOL_MARKERS.get(token, 0.0)

programs.sol:
"""A lexical ca-/car- detector, strongest on short word pieces.

The rule is mainly spelling, not car-related meaning: 'card', 'cal', and
'cam' are also strong. Longer ca- words are weaker, with a few common
lexical exceptions. It includes ka-like spellings in other scripts and
smaller signals for cell, character, heart, and Chinese ability words.
Adjacent pronouns modulate 'can'; its negative contraction is negative.
Only the current and previous token in the same document are used.
"""
READS = ()


def strength(token, previous=''):
    word = token.strip().lstrip('._-/(<["').lower()
    if word.startswith('ca'):
        if word in ('car', 'cars'):
            if token.startswith('-'):
                return 3.05
            return 3.9 if word == 'car' else 3.25
        if word in ('ca', 'cal', 'cam', 'card', 'cards'):
            return 2.6
        if word in ('cat', 'cats', 'cast', 'care', 'cares'):
            return 1.95
        if word == 'can':
            if token.strip() != 'can':
                return 1.65
            subject = previous.lower()
            if subject in ('you', 'we'):
                return 0.8 if previous == 'You' else 1.05
            if subject == 'i':
                return 1.3
            if subject in ('it', 'this', 'that'):
                return 1.7
            if subject == 'how':
                return 0.9
            return 1.5
        if word == 'cap':
            return 1.4
        if word == 'came':
            return 0.05
        if word.startswith(('called', 'calling', 'cannot', 'catch',
                            'caught', 'cache', 'cancel', 'capital',
                            'captain', 'career', 'cargo')):
            return 0.25
        if word.startswith('camera'):
            return 1.7
        if (len(word) == 4 and word.startswith('car')
                and word[-1] not in 'aeiout'):
            return 2.1
        if word == 'calcium':
            return 2.0
        return 0.8
    if word.startswith('cell'):
        return 1.0
    if word.startswith('character'):
        return 1.1 if word in ('character', 'characters') else 0.65
    if word in ('ica', 'ican', 'eca'):
        return 1.0
    if word in ('ocal', 'cation'):
        return 1.4
    if word == 'ical':
        return 0.5
    if word in ('ka', 'ika', 'ка'):
        return 0.5
    if word in ('か', 'のか'):
        return 1.55
    if word in ('カル', 'キャ', '카'):
        return 3.0
    if word.startswith(('カ', 'キャ')):
        return 2.0 if len(word) == 1 else 1.7
    if word == '卡':
        return 3.5
    if word in ('heart', '心', '加', '车', '車'):
        return 0.85
    if word in ('能力', '的能力'):
        return 1.4
    if word == '可以':
        return 0.6
    if word in ("'t", '’t'):
        if previous.lower() == 'can':
            return -0.35
        if previous.lower() == 'couldn':
            return -0.23
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (len(prefix.token_ids) > 1
            and prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2].strip()
    return None, float(strength(prefix.token_strings[-1], previous))

programs.haiku:
"""layers.0.mlp.down_proj:2570 — a lexical "word starts with ca-" detector.

This component is almost entirely a function of the current token's spelling. It
switches on for words that begin with the hard-C sound spelled "ca" (car, cam, cal,
cat, can, cap, cast, care, case, call, ...), strongest for the short car/cam/cal/card
family, and weaker for longer or unrelated "ca" words. Words that merely begin with
"c" (come, code, count, clear, ...) stay near zero, and the effect does not depend on
the surrounding text.

Prediction: a fixed value per token, read from its spelling (leading space and case
ignored), with 0 elsewhere.
"""

READS = ()

# Short "car / cam / cal / cat / cast / care / card / cap" words: the strongest responders.
CA_SHORT = {
    "car", "cars", "cam", "cal", "card", "cast", "cat", "care", "carb", "cap",
    "ca", "cas", "caps", "cats", "camp", "cart", "calc", "calcium",
}  # fmt: skip
# "can" (modal or noun), a common and clear case.
CA_CAN = {"can", "cans"}
# "ca" words that do not respond much.
CA_WEAK = {
    "came", "career", "careers", "careful", "carefully", "careless", "cargo", "cannot",
    "cabinet", "candle", "capital", "cave", "cash", "cancel", "cancelled", "camping",
}  # fmt: skip
# Related words spelled with a hard c followed by "e" or "ch" that respond moderately.
CE_CH = {"cell", "cells", "character", "characters"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in CA_SHORT:
        value = 2.5
    elif word in CA_CAN:
        value = 1.4
    elif word in CA_WEAK:
        value = 0.2
    elif word.startswith("ca"):
        value = 0.8
    elif word in CE_CH:
        value = 0.9
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A small script cue: Arabic-script pieces tend positive, Cyrillic pieces negative."""
import unicodedata

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    scripts = {unicodedata.name(c, "") for c in token if c.isalpha()}
    if any("ARABIC" in name for name in scripts):
        return None, 0.14
    if any("CYRILLIC" in name for name in scripts):
        return None, -0.07
    return None, 0.0

"""Estimate a layer-zero feature for backgrounds, environments, and situations.

It scores those words positively, with larger responses for "background" and
smaller ones for broader scene or life terms. A preceding "background" also
raises the next colon or "of", as in a heading. This lexical rule misses
sentence-specific activation changes.
"""
READS = ()

BACKGROUND = {"background"}
ENVIRONMENT = {
    "environment", "environments", "environmental", "environmentally",
    "atmosphere", "atmospheric", "ambient", "ecosystem", "ecosystems",
    "habitat", "habitats", "scene", "scenes", "surroundings",
    "foreground", "env", "_env",
}
SITUATION = {
    "context", "contexts", "scenario", "scenarios", "situation",
    "situations", "circumstance", "circumstances", "condition",
    "conditions", "setting", "settings", "setup", "perspective",
    "perspectives", "world", "worlds", "life", "lives", "ground",
    "grounded", "baseline", "case", "cases",
}
INTRODUCTION = {"introduction"}


def _word(token):
    return token.strip().strip(".,:;!?()[]{}\"'`).，。；：！？、（）")


def step(carry, prefix, upstream):
    """Score the current setting-related word and a short background heading."""
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    word = _word(prefix.token_strings[-1])
    low = word.lower()

    if low in BACKGROUND:
        value = 4.4
    elif low in ENVIRONMENT:
        value = 1.3
    elif low in SITUATION:
        value = 0.8
        if low in {"context", "contexts", "scenario", "scenarios", "situation", "situations"}:
            value = 1.2
        elif low in {"world", "worlds", "life", "lives"}:
            value = 0.75
        elif low in {"conditions", "condition", "objective", "objectives", "baseline"}:
            value = 0.35
        elif low in {"ground", "grounded", "case", "cases"}:
            value = 0.55
    elif low in INTRODUCTION:
        value = 1.2
    elif low == "introductory":
        value = 0.6
    elif low in {"環境", "背景", "场景", "情境", "情况", "生命", "世界", "設定", "设置", "場合"}:
        value = 0.8
        if low in {"情况", "场景"}:
            value = 1.2
        elif low == "背景":
            value = 3.0
    elif low == "应用场景":
        value = 1.6
    else:
        value = 0.0

    previous = {w.lower() for w in recent[-2:]}
    if low in {":", "："} and "background" in previous:
        value = 1.1
    elif low == "of" and "background" in previous:
        value = 3.0

    return (doc, (recent + (word,))[-4:]), float(value)

programs.haiku:
"""Comparison-word detector for layers.0.mlp.down_proj:2574.

The component is a strongly negative detector for the word that opens the second
term of a comparison, "than". It is most negative right after "more" (about -9),
less after "less"/"fewer" (about -4.5) and after comparative adjectives ending in
"-er" such as "greater", "larger", "higher", "faster" or "better" (about -4 to -6).
Shortly after such a comparative word it is weaker (about -3.5). "rather than" and
"other than" are not comparisons and get 0. German "als" after "mehr", "weniger" or
"länger" (more / less / longer) gets about -3. Everything else gets 0.
"""

READS = ()

MORE_LESS = {"more": -9.0, "less": -4.5, "fewer": -4.5}
GERMAN_COMPARATIVE = {"mehr": -3.0, "weniger": -3.0, "länger": -3.0}
NOT_COMPARATIVE = {"rather", "other", "never", "ever", "after", "under", "over", "number"}


def _word(text):
    return text.strip().lower()


def _is_comparative_adjective(word):
    return word.endswith("er") and word not in NOT_COMPARATIVE and len(word) > 3


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    # A comparison cannot span a document boundary.
    if len(tokens) < 2 or docs[-2] != docs[-1]:
        return carry, 0.0
    word = _word(tokens[-1])
    before = _word(tokens[-2])
    value = 0.0
    if word == "than":
        if before in MORE_LESS:
            value = MORE_LESS[before]
        elif before in ("rather", "other"):
            value = 0.0
        elif before == "better" or _is_comparative_adjective(before):
            value = -5.0
        elif any(_word(x) in MORE_LESS for x in tokens[-5:-1]):
            value = -3.5
    elif word == "als" and before in GERMAN_COMPARATIVE:
        value = GERMAN_COMPARATIVE[before]
    return carry, float(value)

