import re

READS = ()


def colon_value(token, line, after_newline):
    if '**:' in token:
        return -4.2
    if ':**' in token:
        return -3.36
    mark = token.strip()
    # Operators, URLs, and escaped colons are not label endings.
    if '::' in token or not mark.endswith((':', '：')):
        return 0.0
    if line.endswith('**'):
        return -2.1 if '\n' in token else -4.7
    if '\n\n' in token:
        return 0.0
    if "':" in token or '\":' in token:
        return -0.07
    if token.startswith(' '):
        return -0.13
    if re.search(r'[)\]}]:$', mark):
        return -0.10 if '\n' in token else -0.80
    if mark.endswith('`:'):
        return -1.17
    words = line.split()
    word = words[-1] if words else ''
    title = word.istitle()
    indent = len(line) - len(line.lstrip())
    numbered = bool(re.match(r'\s*\d+[.)]\s', line))
    if '\n' in token:
        return -0.19 if title else (-0.10 if len(line) < 20 else 0.03)
    if '：' in token:
        return -0.94 if len(line) < 20 else -0.42
    if title:
        if len(line) >= 40:
            return -0.44
        if numbered:
            return -1.96
        if len(word) < 3:
            return -0.52
        if indent >= 3:
            return -0.41
        return -1.09 if after_newline else -0.53
    if any(c in line for c in '{}[]=();'):
        return -0.69 if numbered else -0.11
    if len(line) < 15:
        return -0.34 if indent else -0.78
    if numbered:
        return -0.94
    return -0.12 if len(word) >= 20 else -0.37


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, after_newline = '', False
    else:
        line, after_newline = carry[1:]
    token = prefix.token_strings[-1]
    mark = token.strip()
    value = 0.0
    if ':' in token or '：' in token:
        value = colon_value(token, line, after_newline)
    elif mark in ('-', '–', '—'):
        if not line.strip():
            value = {'-': -0.81, '–': -0.54, '—': -0.32}[mark]
            if token.startswith(' ') and mark == '-':
                value = -1.40
        elif token == ' –':
            value = -0.56 if len(line) < 40 else -0.28
        elif token == ' -' and line.endswith(' '):
            value = -0.88
        elif token.startswith(' ') and len(line) < 18 and after_newline:
            value = -0.20
        elif token == ' -' and line.split()[-1].istitle():
            value = -0.17
        else:
            value = -0.03
        if '\n' in token:
            value *= 0.24
    elif token == '】':
        value = -0.60
    elif token in ('**', '**\n', '**\n\n', ')**', ' **'):
