    elif head == 'item' and word in {'ize', 'ized', 'izes'}:
        value = 1.6
    elif head == 'problem':
        if word in {'solving', '-solving', 'solver'}:
            value = 0.95
        elif word in {'statement', 'description'}:
            value = 0.6 if word == 'statement' else 0.85

    if word.isalpha() and not word.isascii():
