        if previous.isdecimal():
            value = -0.62 - 0.31 * early
            value -= 0.15 if last == '0' else 0.04 if last == '1' else 0.0
            value += 0.13 if line_number else 0.0
            if before_number in {'_', '/', '@'}:
                value -= 0.24
            elif before_number in {'(', '[', '{', '"', "'"}:
                value -= 0.29
            elif before_number == ',':
                value -= 0.17
            elif before_number in {'-', '−'}:
                value -= 0.06
            if number_length > 4:
                value -= 0.10
