    elif text.rstrip('\r\n') == '..':
        value = -0.73 if previous.isdecimal() else -0.50
    elif text.startswith(' ,') and not text[2:].strip():
        value = -0.53
    elif text == '．':
        value = -1.04
    elif text in {'/.', ' ./'}:
        value = -1.75 if text == '/.' else -0.97
    elif text == ' ..':
        value = -1.22
    elif text in {'*.', '!.', '?.', ':.', ',.', '+.', '-.'}:
