            return -0.03
        if width <= 6:
            return 0.02
        if width <= 24:
            return -0.04
        return 0.08
    if width == 1:
        return 0.0
    if width == 2:
        return 0.58
    if width == 3:
        return 0.64
    if width <= 11:
        return 0.46 * 0.80 ** (width - 4)
    return -0.03


def continuation_strength(previous, token):
    match = re.search(r'[A-Za-z]+$', previous)
    fragment = match[0] if match else ''
    if len(fragment) == 1:
        capital = fragment.isupper()
        if token[0].lower() in VOWELS:
            return 0.04 if capital else 0.02
        if fragment.lower() in VOWELS:
            return 0.04 if capital else -0.01
        return 0.14 if capital else 0.07
    if fragment and len(token) <= 2:
        return 0.01 if fragment.isupper() else -0.015
    return 0.0


