        value = padding_strength(len(token), line_start)
    elif token and token == '\xa0' * len(token):
        value = 0.14 if 2 <= len(token) <= 3 else -0.02
    elif token.isspace() and '\t' in token:
        value = -0.04
    elif token.isspace() and token.startswith('   '):
        value = 0.03 if line_start else 0.20
