    if s.startswith('::<'): return 4.1

    if s.startswith('(') and s.count('(') > s.count(')'):
        rest = s[1:]
        if spaced:
            if '\n' in rest: return 0.15
            if line_start: return 0.5
            if rest.startswith(('(', '[', '{', '<')): return 0.0
            if previous.rstrip().endswith(('.', '?', '!', '"', "'")):
                return 0.5
            if word in CONTROL_OR_CONNECTIVE_WORDS: return 1.15
            if previous.rstrip().endswith(('+', '-', '/', '*', '=', ',')):
                return 1.3
            return 0.8
        if '\n' in rest: return 0.6
        if line_start: return 0.2
        if rest:
            if rest.startswith(':,'): return 3.3  # a matrix slice
            if rest.startswith(('[', '{', '(')): return 0.9
            if rest[0] in "\"'": return 1.35
            if rest.startswith('\\"'): return 1.8
            if rest in TYPES or rest == 'self': return 1.55
            if rest[0].isalpha() or rest[0] == '_':
                return 1.7 + 0.27 * length_cue(rest)
            return 1.4
        if word: return 1.1 + 0.55 * length_cue(word)
        return 1.15 if previous[-1:].isdigit() else 1.0

    if s.startswith('[') and ']' not in s:
        rest = s[1:]
        if '\n' in rest: return 0.0
        if spaced:
            if rest: return 0.95
            return (0.85 if previous.rstrip().endswith((':', '=', ',', '+', ']'))
                    else 0.25)
        if rest:
            if rest.startswith('/'): return 1.4  # closing BBCode-style tag
            if rest[0] in "\"'": return 3.7
            if rest[0].isalpha() or rest[0] == '_':
                if line_start: return 0.45
                if word == 'map': return 9.4  # Go map key-type bracket
                return 4.15 + 0.87 * length_cue(rest)
            return 3.35 if rest.startswith(('-', '+', ':')) else 1.7
        if line_start: return 0.0
        if word: return 2.5 + 0.9 * length_cue(word)
        return 2.0 if previous[-1:].isdigit() else 0.6

    if s.startswith('{') and '}' not in s:
        rest = s[1:]
        if '\n' in rest:
            if spaced: return 0.0
            return 0.85 if word else -0.4
        if spaced:
            if rest.startswith('"'): return 1.8
            if rest.startswith('\\'): return 1.0
            return 2.2 if word in TEX_FRACTION else 0.9
        if rest.startswith('"'): return -0.13 if line_start else 1.15
        if rest: return 2.6 if rest.startswith('\\') else 1.8
        if word in TEX_FRACTION: return 4.6
        if word in TEX_ENVIRONMENT: return 0.55
        if word in TEX_STYLE: return 3.85
        if word in TEX_TEXT: return 3.2
        if word in TEX_REFERENCE: return 1.75
        if line_start or previous.isspace(): return 0.1
        return 2.6 if word else 1.3

    if s.startswith('<') and '>' not in s:
        rest = s[1:]
        if spaced or rest.startswith(('/', '<', '=', '!', '?')) or '\n' in rest:
            return 0.0
        if rest.startswith('_'): return 3.6  # inferred type placeholder
        if rest[:1].isalpha():
            if (rest in TYPES or rest[0].isupper()) and len(word) > 1:
                return 4.85 + 0.6 * length_cue(rest)
            return 0.3 if rest in TYPES or rest[0].isupper() else 0.0
        if rest.startswith("'"): return 4.25  # Rust lifetime parameter
        if not rest and len(word) > 1: return 3.2 + 0.5 * length_cue(word)
        return 0.3 if not rest else 0.0

    # Openings combined with operators or closing punctuation are weaker.
    if '(' in s and s.rfind('(') > s.rfind(')'):
        if s.startswith('\\'): return 0.1
        if s[0] in ']})' or s.count('(') <= s.count(')'): return 0.55
        return 2.7 if s.startswith('__') else 1.3
    if '{' in s and '}' not in s:
        if '\n' in s: return -0.15
        if s.startswith('_'): return 2.35
        if s.startswith('^'): return 2.2
        return 1.2 if s.startswith('=') else 0.7
    if '[' in s and ']' not in s: return 0.75
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    return None, float(activation(prefix.token_strings[-1], previous))

