programs.sol:
"""A surface plural/possessive-ending detector, not a full number parser.

Most single-s endings give a strong negative response, including endings
of code identifiers. Double-s, -ous, function words and common verb forms
are weaker. A word-fragment buffer distinguishes possessives from 'it's'
and an attached s from a standalone letter. It also recognizes some
irregular and Chinese plural forms.
A separate negative case covers the tool-call opening marker.
Most other text is nearly zero.
"""
import re
READS = ()

UNINFLECTED = set('''is was this his thus always perhaps sometimes towards
whereas themselves ourselves yourselves otherwise plus focus'''.split())
FUNCTION = {'as', 'has', 'us', 'its'}
EUROPEAN_FUNCTION = {'des', 'das', 'les', 'es', 'pas', 'dans', 'aus'}
VERBS = set('''does goes comes becomes seems gives takes makes says means
allows contains requires includes exists provides follows shows uses extends
begins ends remains appears happens depends satisfies represents relates
suggests continues leads enables occurs looks sees feels helps tells thinks
knows consists comprises implies involves equals'''.split())
SINGULAR = set('''gas lens bias chaos virus campus corpus consensus diabetes
status'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('./_-(\'"')
    match = re.search(r'\w+$', previous + token.lower())
    state = (doc, match[0][-40:] if match else '')
    attached = bool(previous and token and token[0].isalpha())
    value = -0.01
    if token in {"'s", '’s'}:
        if previous == 'it':
            value = 0.08
        elif previous in {'that', 'there', 'what', 'who', 'he', 'she'}:
            value = -0.17
        else:
            value = -1.17
    elif word in {'people', 'children', 'criteria', 'phenomena'}:
        value = -1.10
    elif word in {'men', 'women', 'teeth', 'feet', 'mice'}:
        value = -0.70
    elif word in UNINFLECTED and not attached:
        value = -0.02
    elif word in FUNCTION and not attached:
        value = -1.03 if word == 'its' else -0.77
        if word == 'as' and previous in {'such', 'well', 'far'}:
            value = -0.13
    elif word in EUROPEAN_FUNCTION and not attached:
        value = -0.51
    elif word in VERBS or word in {'series', 'species', 'news'}:
        value = -1.10
    elif word in SINGULAR or word in {'https', 'css', 'trans', 'cos', 'yes'}:
        value = -0.60
    elif word == '<tool_call>':
        value = -1.10
    elif word == 'doesn':
        value = -0.90
    elif token in {'.js', '/js'}:
        value = -0.90
    elif word.endswith('s'):
        if word.endswith('ss'):
            value = -0.03 if token[:1].isspace() and not attached else -0.24
        elif word.endswith(('ous', 'sis')):
            value = -0.32
        elif word.endswith(('is', 'us')):
            value = -0.76
        elif len(word) == 1:
            value = -0.8
            if attached:
                value -= 0.17 * min(len(previous), 6)
            if previous[-1:].isdigit():
                value = -1.05
        else:
            value = -1.2 - 0.08 * min(len(word), 8)
            if word.endswith(('as', 'os')):
                value += 0.35
            if token.startswith(('.', '/', '_')):
                value -= 0.2
            if word.endswith(('ts', 'ds', 'ks', 'ps', 'ies')):
                value -= 0.12
    elif word in {'с', 'σ'} and not attached:
        value = -0.20
    elif word.endswith(('с', 'ς', 'σ', 'ſ')):
        # Cyrillic/Greek counterparts of s, and historical Latin long s.
        value = -0.62
    elif word.endswith(('们', '們')):
        # Chinese personal plural suffix (simplified and traditional).
        value = -2.0 if len(word) == 1 else -0.9
    elif word == 'those':
        value = -0.40
    elif word == 'these':
        value = 0.23
    return state, value

