# Words ending in 's' that are not plurals or verbs.
NOT_PLURAL = {"always", "perhaps", "towards", "sometimes", "whereas", "themselves", "ourselves",
              "this", "is", "was", "his", "thus", "plus", "less", "yes", "class", "process",
              "access", "success", "pass", "mass", "focus", "analysis", "business", "bus", "gas",
              "address", "loss", "cross", "press", "previous", "across", "stress", "excess"}
# Short suffix pieces and the function words / possessives that behave like an 's' ending.
SUFFIX_PIECES = {"s", "es", "os"}
S_LIKE_WORDS = {"as", "has", "its", "us", "'s", "’s", "people", "children", "men", "women"}


def step(carry, prefix, upstream):
