programs.sol:
"""A lexical pull/bull detector, with a weaker livestock association.

The strongest responses are to forms of 'pull', the isolated word-piece
'ull', and 牛 (cow/ox). Related spellings, farm animals and their products,
and pushing/holding get smaller positive responses. A one-token memory
handles split word endings and ignore-file names. Otherwise the prediction
is zero: sentence meaning and most small background responses are omitted.
"""

READS = ()

# Weaker animal and animal-product responses, grouped by fitted strength.
ANIMALS = (
    (1.65, frozenset('cow sheep beef puppy'.split())),
    (1.30, frozenset('cows cattle'.split())),
    (0.90, frozenset('horse pony wolf wolves puppies buffalo'.split())),
    (0.70, frozenset('horses lamb wool calf calves shepherd'.split())),
    (0.50, frozenset('goat livestock dairy camel'.split())),
    (0.30, frozenset('dog dogs chicken milk animal animals'.split())),
)

# Chinese/Japanese vocabulary: cattle, sheep, herding; pull, pluck, push.
# Then pig, dog, hide; dog, bear, deer; hair, milk, chicken, field.
CHARACTERS = {
    '牛': 7.3, '羊': 2.35, '牧': 1.5,
    '拉': 2.3, '拔': 1.5, '推': 0.9,
    '猪': 1.0, '犬': 1.0, '皮': 1.0,
    '狗': 0.7, '熊': 0.7, '鹿': 0.7,
    '毛': 0.65, '奶': 0.5, '雞': 0.5, '田': 0.7,
}


def token_strength(token):
    word = token.strip().lower()
    value = 0.0
    if word in ('pull', 'pulls', 'pulled', 'pulling'):
        value = 5.5 if word == 'pulled' else 6.0
        if word in ('pull', 'pulls') and token.startswith(' '):
            value = 6.4
        if word == 'pull' and token.strip().istitle():
            value = 6.6
    elif word in ('_pull', '.pull'):
        value = 5.7 if word.startswith('_') else 3.9
    elif word == 'ull':
        value = 6.6 if token.isupper() else 5.35
    elif word in ('ulls', 'ulled', 'ulling'):
        value = 4.1
    elif word == 'bull':
        value = 5.8 if token.startswith(' ') else 4.5
    elif word == 'bulls':
        value = 3.5
    elif word == 'mull':
        value = 3.6
    elif word in ('ulla', 'ullo', 'ulle', 'ully', 'ullan', 'hull', 'skull'):
        value = 1.9
    elif word in ('bullying', 'bullshit'):
        value = 2.1
    elif word == 'bul':
        value = 0.7
    elif word in ('push', 'pushes', 'pushed', 'pushing') or word == '.push':
        value = 1.0
    elif word == 'tug':
        value = 1.85
    elif word in ('tow', 'towing', 'tearing'):
        value = 0.8
    elif word == 'held':
        value = 0.57
    elif word in ('hold', 'holds', 'holding'):
        value = 0.30
    elif word in CHARACTERS:
        value = CHARACTERS[word]
    elif word in ('牛肉', '羊毛'):
        value = 2.5
    elif word == '牛市':  # 'bull market'
        value = 4.4
    elif word in ('牛奶', '羊肉'):  # milk, mutton
        value = 1.1
    elif word in ('拉动', '拉开'):
        value = 1.6
    else:
        for strength, words in ANIMALS:
            if word in words:
                value = strength
                break
    return value


def step(carry, prefix, upstream):
    """Distinguish a few split words and ignore-file names across tokens."""
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.lower()
    value = token_strength(token)

    # A suffix can continue a high-response stem: Pull + ing, Mull + er.
    if previous == 'pull' and word in ('ing', 's'):
        value = 4.3 if word == 'ing' else 3.6
    elif previous in ('ull', 'mull', 'bull') and word in (
        'er', 'ie', 'ies', 'ied', 'en', 'ing', 's'
    ):
        value = 1.3
    elif token == 'ull' and previous.strip(' /-_') in ('p', 'b'):
        value = 6.6
    elif token == 'ignore':
        value = 0.55
        if previous.endswith('git'):
            value = 0.96
        elif previous.endswith(('docker', 'lint')):
            value = 0.77

    return (document, token.strip().lower()), value

programs.haiku:
"""Component layers.0.mlp.down_proj:2584: a word detector for "pull" (and "bull").

The component is lexical. Its activation is mostly fixed by the current word: a lookup
table of each word's typical activation explains about 0.8 of the variance in-sample.
It responds most to "pull" in any form (pull, pulls, pulled, pulling; with or without a
leading space; any capitalisation), at about 6, and to the "-ull" spelling of "bull"
(bull, bulls, and the bare "ull" piece), at a similar size. Weaker responses come from
other "-ull" words (Mull, Hull, skull, about 2), from push words (about 1), from cattle,
sheep and horse words (about 1 to 2), and from some Chinese words: 牛 (cow, about 7),
羊 (sheep), 拉 (pull), 推 (push), and other Chinese animal words (about 0.7).

The program reads only the newest token, so it is causal and keeps no state. Its
prediction is each word's typical activation, not an exact model of the network. On
held-out text it explains about half the variance.
"""

READS = ()

# Forms of "pull" and "bull", and the bare "ull" piece: the strongest responses.
CORE = {"pull", "pulls", "pulled", "pulling", "bull", "bulls", "ull", "ulls", "ulling"}
# Other words with the "-ull" spelling.
ULL = {"mull", "hull", "skull", "skulls", "bullying", "bullshit", "ulla", "ulle"}
# English cattle, sheep, horses, wolves and similar.
LIVESTOCK = {"cow", "cows", "cattle", "beef", "sheep", "goat", "lamb", "horse", "horses",
             "wolf", "wolves", "pony", "buffalo", "cowboy", "calf", "dairy", "livestock"}
# Chinese: 牛 cow, 羊 sheep, 拉 pull, 推 push; the next set is animals and animal products.
CHINESE = {
    "牛": 7.0, "牛肉": 2.4, "羊": 2.3, "羊毛": 2.8, "拉": 2.3, "拉动": 1.7, "推": 0.9,
}
CHINESE_ANIMALS = set("猪豬犬狗鹿鹰虎熊雞鸡狼驴蛇龍龙皮毛奶卵")
PUSH = {"push", "pushed", "pushes", "pushing"}


def step(carry, prefix, upstream):
    # The newest token, lower-cased with its leading space removed.
    word = prefix.token_strings[-1].strip().lower()
    if word in CHINESE:
        return carry, CHINESE[word]
    if word in CORE:
        return carry, 6.0
    if word in ULL:
        return carry, 2.0
    if word in LIVESTOCK:
        return carry, 1.5
    if word in CHINESE_ANIMALS:
        return carry, 0.7
    if word in PUSH:
        return carry, 1.0
    return carry, 0.0

programs.sol:
"""Approximate a separator-versus-line-marker contrast, chiefly on hyphens.

The main hyphen rule is positive after words, weaker after numbers, and
negative at line starts. Spacing and fused word fragments soften the signal.
Related punctuation gets calibrated versions of the same left-context score.
This deliberately ignores lexical identity and predicts zero on ordinary text.
"""
READS = ()


def left_context(previous, before_previous, line_start):
    """Describe the left side as a word, number, boundary, or punctuation."""
    word = previous.strip()
    last = previous[-1:]
    if not previous:
        return -3.0
    if line_start:
        if not word:
            return -3.3 if previous.count('\n') == 1 else -3.0
        return -2.7 if any(c in previous for c in ':?') else -3.0
    if previous.endswith('\\n'):
        return -0.85
    if last.isspace():
        return -1.9
    if last.isdigit():
        return -0.35 if '-' in before_previous else 0.44
    if last.isalpha():
        if len(word) == 1:
            if not word.isascii():
                return 0.95
            return 0.8 if word.isupper() else 0.56
        value = 1.5 if len(word) >= 3 else 1.35
        if not word.isascii():
            value += 0.25
        if '-' in before_previous or word.startswith('-'):
            value -= 0.4
        if word.startswith('('):
            value -= 0.8
        return value
    return -0.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, line = '', '', ''
    else:
        _, previous, before_previous, line = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    spaced = token[:1].isspace()
    newline = '\n' in token
    left = left_context(previous, before_previous, not line.strip())
    value = 0.0
    if s == '-':
        if newline:
            value = 0.1 if spaced else 0.54 * left + 0.12
        else:
            value = 0.24 * left - 0.11 if spaced else left + 0.03
    elif len(s) > 1 and s[0] in '-/_' and s[1:].isalpha():
        # A separator fused to a word fragment carries a softened signal.
        context = left if previous else 0.0
        positive, negative = max(context, 0.0), min(context, 0.0)
        upper, length = s[1:].isupper(), min(len(s) - 1, 8)
        if s[0] == '-':
            value = 0.40 * positive + 0.90 * negative
            value += -0.12 + 0.23 * upper - 0.08 * length
        elif s[0] == '/':
            value = -0.19 + 0.12 * context + 0.12 * upper
        else:
            value = -0.09 + 0.09 * positive + 0.21 * negative
            value += 0.09 * upper - 0.01 * length
    elif s in ('‐', '‑'):
        value = 1.17 + 0.36 * left
    elif s == '/':
        value = 0.43 * left
        if spaced:
            value = 0.02
        elif newline:
            value = 0.15 * left - 0.15
    elif s == '_':
        value = 0.42 * left + 0.17
        if spaced:
            value = 0.08
        elif newline:
            value = 0.10 * left + 0.16
    elif s in ('–', '—', '―'):
        en_dash = s == '–'
        value = 0.36 + 0.39 * left + en_dash * (0.10 + 0.11 * left)
        if spaced:
            value = 0.18 + 0.18 * en_dash + 0.03 * left
    elif s == '+':
        value = 0.28 * left - 0.12
        if spaced:
            value = 0.0
        elif newline:
            value = 0.16 * left - 0.23
    elif s == '--':
        value = 0.21 + 0.1 * left if spaced else 0.27 + 0.3 * left
    elif s in ('•', '·', '・'):
        value = 0.73 + 0.37 * left - 0.42 * (s == '・') - 0.46 * (s == '·')
        if spaced:
            value -= 0.41 + 0.28 * left
    elif s == '\\_':
        value = 0.47 + 0.29 * left
    elif s == '\\-':
        value = -1.22 + 0.16 * left
    line = (line + token).rsplit('\n', 1)[-1][-100:]
    return (doc, token, previous, line), float(value)

programs.haiku:
"""Hyphens, dashes and joiners in text.

Layer-0 MLP unit 2586 is a "dash in context" detector:
- a hyphen that opens a line (a Markdown / list bullet "- item", after a newline or
  indentation) drives it strongly negative;
- a hyphen, en dash, slash or underscore that joins word pieces ("anti-inflammatory",
  "COVID-19", "_modules", "a/b") drives it positive, most after a letter, less after a digit.
Everything else is ~0.
"""

READS = ()

DASH_CHARS = {"–", "—", "‐", "‑", "−"}  # en/em dash, hyphens, minus
BULLET_CHARS = {"+", "•", "·", "*"}                   # other list markers
JOINERS = {"/", "_"}


def _is_hyphen_run(tok):
    return tok.rstrip("\n") != "" and set(tok.rstrip("\n")) == {"-"}


def _line_start(prefix):
    # first token of a document, or right after a newline or indentation
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return True
    prev = prefix.token_strings[-2]
    return prev.endswith("\n") or prev.strip() == ""


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if _line_start(prefix):
        if _is_hyphen_run(tok):
            return None, -2.3
        if tok.rstrip("\n") in DASH_CHARS | BULLET_CHARS:
            return None, -0.7
        return None, 0.0
    before = prefix.token_strings[-2][-1:]  # the character just before this token
    after_letter = before.isalpha()
    after_digit = before.isdigit()
    if _is_hyphen_run(tok):
        if after_letter:
            return None, 1.2
        if after_digit:
            return None, 0.4
        return None, -0.4
    if tok in DASH_CHARS:
        return None, 0.9 if after_letter else (0.6 if after_digit else 0.0)
    if tok in JOINERS and after_letter:
        return None, 0.7
    return None, 0.0

