"""Use nearby text boundaries to make a small signed dash prediction."""
READS = ()
DASHES = "-‐‑‒–—―−"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()
    same_doc = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    prior = prefix.token_strings[-2] if same_doc else ""
    value = 0.0

    if text.startswith(tuple(DASHES)):
        if prior.endswith(("\n", "\r")):
            value = -1.0
