programs.sol:
"""Book/catalogue cues and lower-case single-word lists.

Book terminology gets a short-lived start-of-document boost. Newlines and
line starts get larger values during runs of equal-length lower-case ASCII
words, a simple detector for the synthetic spelling/permutation lists seen
in training. A few explicit document and formatting markers are separate.
Ordinary prose's numerous small lexical fluctuations are not modeled.
"""
import math

READS = ()
EBOOKS = {'ebook', 'ebooks'}
PUBLICATIONS = set('book books handbook manual manuals bible isbn edition'.split())
SOLUTIONS = {'solution', 'solutions', 'answer', 'answers'}
STUDY = set('guide workbook chapter exam tutorial calculus fundamentals'.split())
MARKERS = {'<tool_call>': -0.11, '<think>': 0.095,
           '<|im_end|>': -0.030, 'etc': 0.13, '://': 0.085}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0, 0)
    _, position, line, previous_length, run = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word if word.islower() else ''
    value = -0.0005 + MARKERS.get(word, 0.0)
    strength = (1.4 if lower in EBOOKS else 0.85 if lower in SOLUTIONS
                else 0.7 if lower in PUBLICATIONS else 0.4 if lower in STUDY
                else 0.0)
    value += 0.5 * strength * math.exp(-position)
    if lower in {'solution', 'solutions'}:
        value += 0.054
    if lower in {'pdf', 'download', 'downloads'}:
        value += 0.068
    if position == 0:
        if word and set(word) == {'#'}:
            value += 0.34 / len(word)
        elif word.isascii() and word.isalpha() and word[0].isupper():
            value += 0.04
    if '\n' in token:
        finished = line + token.split('\n', 1)[0]
        length = len(finished)
        single_word = (finished.isascii() and finished.isalpha()
                       and finished.islower() and 5 <= length <= 20)
        run = run + 1 if single_word and length == previous_length else 0
        previous_length = length if single_word else 0
        value += 0.03 * single_word
        if run:
            value += 0.273 * (1 - 0.5 * math.exp(-run / 3))
        line = token.rsplit('\n', 1)[-1]
        if token.count('\n') > 1:
            run, previous_length = 0, 0
    else:
        if not line:
            value += 0.088 * min(run / 3, 1.0)
        line = (line + token)[-200:]
    return (doc, position + 1, line, previous_length, run), float(value)

programs.luna:
"""Small positive cues for new-text boundaries, reference-book terms, and
repeated anagram-like lines; most positions get no prediction."""
from collections import Counter

READS = ()
REFERENCE_WORDS = {
    "bible", "quran", "ebook", "ebooks", "pdf", "solution", "solutions", "manual"
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    new_doc = carry is None or carry[0] != doc
    if new_doc:
        line, old_signatures = "", ()
    else:
        _, line, old_signatures = carry

    value = 0.01 if new_doc else 0.0
    if len(prefix.token_strings) > 1 and prefix.token_strings[-2] == "<|endoftext|>":
        value = max(value, 0.035)
    if token.strip().casefold() in REFERENCE_WORDS:
        value = max(value, 0.05)

    if "\n" in token:
        before, after = token.rsplit("\n", 1)
        line = (line + before).strip()
        if 6 <= len(line) <= 28 and line.isascii() and line.isalpha():
            signature = tuple(sorted(Counter(line).items()))
            if signature in old_signatures:
                value = max(value, 0.01)
            old_signatures = (signature,) + old_signatures[:3]
        line = after
    else:
        line = (line + token)[-160:]

    return (doc, line, old_signatures), float(value)

