             'teamwork coordination cohesion'.split())
EMOTION = set('emotion emotions emotional empathy temperament smell sniff'.split())
DEVELOPMENT = set('development developmental develop developed developing'.split())
MEMORY = set('memory memories memor'.split())
DECISION = set('decision decisions decide choice choices'.split())
ANIMAL_TRAITS = set('tail tails wings flight diet feeding jaws claws fins mating mate mates'.split())
DEFENSE = set('avoid avoiding avoidance defend defensive defense defence'.split())
ENVIRONMENT = set('environment environmental resources resource efficiency efficient advantage'.split())

GROUPS = (
    (ADAPTATION, 0.85), (SURVIVAL, 0.63), (INSTINCT, 0.78),
    (EVOLUTION, 0.53), (STRATEGY, 0.61), (TACTICS, 0.38),
    (PREFERENCE, 0.40), (NAVIGATION, 0.43), (RESPONSE, 0.45),
    (RESPONSIVENESS, 0.28), (COGNITION, 0.38), (LEARNING, 0.20),
    (SOCIAL, 0.23), (EMOTION, 0.34), (DEVELOPMENT, 0.20),
    (MEMORY, 0.22), (DECISION, 0.16), (ANIMAL_TRAITS, 0.26),
    (DEFENSE, 0.23), (ENVIRONMENT, 0.18),
    ({'behaviors', 'behaviours'}, 0.56),
    ({'feathers'}, 0.56), ({'advantageous'}, 0.56),
    (set('behavior behaviour behavioral behavioural'.split()), 0.20),
    ({'adapted'}, 0.62), ({'language', 'languages', 'linguistic'}, 0.21),
    (set('human humans humanity'.split()), -0.15),
    (set('protein proteins receptor receptors cellular mrna cells'.split()), -0.15),
    (set('damage degradation'.split()), -0.22),
    (set('lymph lesion lesions staining microscopy specimen specimens vitro vivo '
         'epith anatom'.split()), -0.25),
    ({'phosphory'}, -0.51),
)
LEVEL = {word: value for words, value in GROUPS for word in words}

# Chinese terms from the same semantic families.
CHINESE = {
    '适应': 1.15, '適應': 1.15, '適': 0.50, '生存': 0.77,
    '策略': 0.59, '策': 0.31, '略': 0.26,
    '响应': 0.46, '应对': 0.32, '社交': 0.42, '协作': 0.40,
    '导航': 0.39, '感知': 0.36, '聪明': 0.30,
    '躲避': 0.80,
    '学习': 0.21, '學習': 0.21, '语言': 0.37, '語言': 0.37,
    '环境': 0.14, '環境': 0.25, '人体': -0.34,
}

BIOLOGICAL = set('immune cellular inflammatory antiviral stress cell'.split())
ADAPT_VERBS = set('adapt adapted adapting adaptive adaptation'.split())
SENSITIVE = set('sensitive sensitivity suited'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ()
    else:
        history = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = history[-1] if history else ''

    value = LEVEL.get(word, CHINESE.get(word, 0.0))
    if word in LEVEL:
        if not token.startswith(' '):
            value *= 0.45
        elif token.strip()[0].isupper():
            value *= 0.75
    if word == 'let':
        value = 0.35 if token.strip() == 'Let' else (0.30 if token == ' let' else 0.15)
    elif word == 'letting':
        value = 0.24
    elif token == '<tool_call>':
        value = 0.084
    elif token == '</tool_call>':
        value = -0.12
    elif token == '</tool_response>':
        value = -0.092

    if word in {'response', 'responses'}:
        if previous == 'immune':
            value = 1.27
        elif previous in BIOLOGICAL:
            value = 0.85
        elif previous == 'in':
            value = 0.77
    elif word == 'selection':
        if previous == 'natural':
            value = 2.0
        elif previous in {'positive', 'habitat'}:
            value = 1.2
    elif word == 'language':
        if previous == 'natural':
            value = 0.78
        elif previous == 'body':
            value = 1.10
        elif previous == 'native':
            value = 0.41
    elif word == 'intelligence':
        if previous == 'human':
            value = 1.0
        elif previous == 'artificial':
            value = 0.25
    elif word == 'skills' and previous == 'social':
        value = 1.0
    elif word in {'skills', 'learning'} and previous in {'motor', 'reinforcement', 'forcement'}:
        value = 0.75
    elif word in {'model', 'models'} and previous in {'animal', 'mouse'}:
        value = -1.0 if previous == 'animal' else -0.55

    if word == 'to' and token == ' to':
        if previous in ADAPT_VERBS or (previous in {'it', 'them'} and len(history) > 1
                                      and history[-2] in ADAPT_VERBS):
            value = 0.96
        elif previous in {'respond', 'response'}:
            value = 0.85
        elif previous in RESPONSE | RESPONSIVENESS:
            value = 0.64
        elif previous in SENSITIVE:
            value = 0.48
        elif previous in {'reply', 'replies', 'reaction', 'reactions', 'conform'}:
            value = 0.33
        elif previous in {'learned', 'trained', 'attracted', 'resistance', 'resistant'}:
            value = 0.23
        else:
            value = 0.009
    elif word == 'for' and previous in ADAPT_VERBS:
        value = 0.75

    if previous == 'adapt' and word in {'ability', 'able', 'ation', 'ations'}:
        value = 1.20
    elif previous == 'social' and word in {'ize', 'izing', 'ization', 'isation'}:
        value = 0.86
    elif previous == 'phosphory' and word in {'lation', 'lated', 'late'}:
        value = -0.45

    return (doc, (*history[-2:], word)), float(value)

