RESPONSE = ("respon", "respond", "adapt", "sensitiv")
CHOICE = ("prefer", "select", "strateg", "tactic")
SURVIVAL = ("surviv", "evolv", "evolut", "navigat", "intellig", "advantag", "skill", "abilit")
TOLERANCE = ("toler", "immun", "avoid", "escap")
LEARNING = ("develop", "language", "learn", "environment", "behavio", "efficien", "optimi", "optimal")
ANIMAL_STEMS = ("hunt", "social", "cooperat", "communicat", "queen", "male", "female", "predat")
ANIMAL_WORDS = ("bee", "nest", "colony", "swarm", "flock", "herd", "prey")
CJK = ("适", "应", "响应", "策略", "选择", "优势", "环境", "群", "巢", "蜂", "雄", "雌", "食", "语言", "配合", "协作", "分工", "女王", "生存", "存活", "进化", "智能")


def starts(word, stems):
    return any(word.startswith(s) for s in stems)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word == "to" and starts(prev, RESPONSE + CHOICE):
        return carry, 0.5
    if word == "let":
        return carry, 0.3
    if starts(word, RESPONSE):
        return carry, 0.3
    if starts(word, CHOICE) or starts(word, SURVIVAL):
        return carry, 0.2
    if starts(word, TOLERANCE) or starts(word, LEARNING):
        return carry, 0.15
    if starts(word, ANIMAL_STEMS) or word in ANIMAL_WORDS:
        return carry, 0.1
    if starts(word, CJK):
        return carry, 0.35
    return carry, 0.0

