"""Negative responses to split East Asian names, titles, and compounds.

A Chinese royal epithet strongly activates a following title/name ending;
ordinary family and place endings are weaker. Several kinship, Korean,
weather, and software compounds are secondary triggers. The rules recognize
literal token pairs, not whether the surrounding text truly denotes royalty.
State consists only of the preceding token and resets between documents.
"""
READS = ()
ROYAL_EPITHETS = set(
    '始太仁穆怀懷偃安桓昭武文高惠孝景宣明成康献獻'
    '灵靈恭玄肃肅宪憲睿庄莊平襄威悼厉厲简簡定哀幽'
    '懿敬靖烈忠贞貞宁寧隆僖厘缪繆'
)
TEMPLE_PREFIXES = set('章世德徽钦欽理哲元')
STATES = set('楚吴吳越周秦齐齊晋晉赵趙燕代魏鲁魯梁宋汉漢纣紂')
# Endings, ordinary response, after a royal epithet, after a state name.
ENDING_GROUPS = (
    ('帝', -0.5, -2.7, -0.9),  # emperor
    ('皇宗', -0.2, -1.7, -0.4),  # imperial / ancestral title
    ('王公', -0.17, -2.2, -1.1),  # king / duke; also public
    ('侯候伯', -0.23, -1.5, -0.3),  # noble ranks and the homophone 候
    ('君子', -0.04, -1.0, -0.1),  # lord / child or master
    ('祖', -0.1, -1.4, -0.5),  # ancestor
    ('陵', -0.45, -1.2, -0.8),  # hill or tomb; place-name ending
    ('州阳', -0.23, -0.9, -0.3),  # prefecture / sun
    ('陽县縣', -0.14, -0.4, -0.25),  # sun / county
    ('武贞貞真', -0.2, -0.9, -0.3),  # martial, faithful, true
)
KINSHIP_COMPOUNDS = {'息子', '天子', '世子', '义子', '義子', '义父', '義父'}
DEITIES = {'关公', '關公', '济公', '濟公'}
KOREAN_COMPOUNDS = {'성공', '성장', '정부'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    value = 0.0
    for endings, ordinary, royal, state in ENDING_GROUPS:
        if len(token) == 1 and token in endings:
            value = ordinary
            if previous in ROYAL_EPITHETS:
                value = royal
            elif previous in TEMPLE_PREFIXES:
                value = 0.55 * royal
            elif previous in STATES:
                value = state
            break
    compound = previous + token if previous and token else ''
    if compound in KINSHIP_COMPOUNDS:
        value = -0.67
    if compound in DEITIES:
        value = -1.5
    if (token in {'帝', '皇', '王', '公', '宗'}
            and previous in {'天', '神', '圣', '聖', '玉'}):
        value = -0.75
    if token == '皇帝':
        value = -1.0 if previous in ROYAL_EPITHETS else -0.4
    if token == '大宗':
        value = -0.5
    if token == '王朝':
        value = -0.45 if previous in STATES or previous == '清' else -0.12
    if token in {'仲', '氏'}:
        value = -0.2
    if token == '県':
        value = -0.1
    if token in {'阴', '陰'} and previous == '淮':
        value = -0.8
    if token in {'阳', '陽'} and previous in {'太', '淮', '高', '平', '烈', '正'}:
        value = -0.6 if token == '阳' else -0.45
    if compound == '全天候':
        value = -0.65
    if compound in KOREAN_COMPOUNDS and not raw.startswith(' '):
        value = -0.48
    if token == 'Studio' and previous == 'Visual':
        value = -0.47
    if token in {'Server', 'Element'}:
        software_prefix = previous in {'SQL', 'Sql', 'Geo', 'Html', 'Svg'}
        value = -0.52 if software_prefix else -0.04
    if token == '.annotation':
        value = -0.87 if previous == '.context' else -0.21
    if token == 'manager' and previous.endswith('context'):
        value = -0.55
    return (doc, token), float(value)

