programs.sol:
"""A lexical contrast between separators and parts of a whole.

Question punctuation, escaped backslashes and selected Unicode marks are
positive; element, aspect and piece words are negative. The negative response continues into
'of' in part-of phrases. Token boundaries affect the strength. Question marks
and the chat speaker 'user' are stronger early in a document. Most small lexical
responses and detailed contextual variation are deliberately omitted. When a
byte-fragment token completes a space, format/control character or Hebrew point,
the decoded prefix identifies it without looking ahead.
"""

import math
import re
import unicodedata

READS = ()

# Unicode formatting functions, not a list of vocabulary IDs.
INVISIBLE = {
    '\x00': 1.70,       # null
    '\x0c': 1.74,       # form feed
    '\r': 0.73,         # carriage return on its own, not CRLF
    '\xad': 2.80,       # soft hyphen
    '\u200b': 1.62,     # zero-width space
    '\u200c': 1.40,     # zero-width non-joiner
    '\u200e': 3.25,     # left-to-right mark
    '\u202b': 0.85,     # right-to-left embedding
    '\ufeff': 2.30,     # byte-order mark
    '\xa0': 0.28,       # nonbreaking space
}
ARABIC_DIACRITICS = {
    'ّ': 1.25,  # shadda: consonant doubling
    'ْ': 1.07,  # sukun: no following vowel
    'ً': 0.85,  # fathatan: doubled vowel mark
    'ُ': 0.58,  # damma
    'َ': 0.40,  # fatha
    'ِ': 0.29,  # kasra
}
PART_WORDS = {
    'element': -1.74, 'elements': -1.51,
    'aspect': -1.33, 'aspects': -1.05,
    'piece': -0.90, 'pieces': -0.56,
    'elemental': -1.24, 'éléments': -1.14,
    'elemento': -0.64, 'elementos': -0.75,
    '元素': -1.30, '要素': -1.50, 'элемент': -1.05,
}
WORD = re.compile(r"^[\s._(\-'\"]*([^\W\d_]+)$")


def part_response(token):
    match = WORD.fullmatch(token)
    if not match:
        return 0.0
    word = match[1]
    value = PART_WORDS.get(word.lower(), 0.0)
    if word in {'Elements', 'ELEMENTS'}:
        value *= 1.35
    if token.startswith('('):
        value *= 0.65
    elif token.startswith('-'):
        value *= 0.80
    elif not token.startswith(' ') and word.isascii():
        value *= 0.90
    return value


def response(token, position, previous):
    bare = token.strip(' ')
    if bare in INVISIBLE:
        scale = 1.0 if bare == token else 0.60
        return INVISIBLE[bare] * scale
    if len(bare) == 1 and unicodedata.category(bare) == 'Cc':
        if bare not in {'\t', '\n'}:
            return 0.90 if bare in {'\a', '\b'} else 0.45
    if bare.startswith('\xad'):
        return 1.70  # soft hyphen attached to a visible suffix
    if bare and set(bare) == {'\u200b'}:
        return 1.80 if token == bare else 1.10
    if bare in ARABIC_DIACRITICS:
        return ARABIC_DIACRITICS[bare]
    if len(bare) == 1 and unicodedata.name(bare, '').startswith('COMBINING'):
        return 1.0
    if '\\\\' in token:
        run = max(len(s) for s in re.findall(r'\\+', token))
        value = {2: 1.44, 3: 0.80, 4: 2.18}.get(run, 2.3)
        return value * (0.90 if token != '\\' * run else 1.0)
    if any(q in token for q in '?？؟'):
        if token.startswith('<?'):
            return 0.0
        value = 0.46 if '?' in token else 0.37
        if '\n' in token:
            value = 0.14 if token.count('\n') > 1 else 0.18
        elif token.rstrip().endswith(('"', "'", '”', '’', ')', ']', ':')):
            value = 0.23
        elif token.count('?') > 1:
            value = 0.35
        early = 0.43 + 0.23 * math.exp(-position / 35)
        if position < 4:
            early = 0.26 if position == 0 else 0.48
        return value * early / 0.46
    value = part_response(token)
    if value:
        return value
    if token == ' of':
        return 0.40 * part_response(previous)
    if token == 'user' and previous == '<|im_start|>':
        return 0.39 + 0.13 * math.exp(-position / 15)
    if bare in {'·', '・', '･'}:
        return 0.55 if token == bare else 0.30
    if bare == 'ſ':  # historical Latin long s
        return 0.59
    # Common leading characters of UTF-8 text misread as Latin-1.
    if bare in {'Â', 'Ã', 'â'}:
        value = {'Â': 0.77, 'Ã': 0.29, 'â': 0.49}[bare]
        return value if bare == token else value * 0.75
    if bare in {'‐', '‑'}:  # Unicode hyphen and nonbreaking hyphen
        return 0.40 if bare == '‐' else 0.77
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    value = response(token, position, previous)
    if position > 0 and token and set(token) == {'\ufffd'}:
        # A UTF-8 continuation can be meaningless alone but complete a character.
        char = prefix.text_prefixes[-1][-1:]
        category = unicodedata.category(char) if char else ''
        if category in {'Zs', 'Zl', 'Zp', 'Cf', 'Cc'}:
            value = {'Zs': 0.50, 'Zl': 0.75, 'Zp': 0.75,
                     'Cf': 0.60, 'Cc': 0.30}[category]
        elif char and unicodedata.name(char, '').startswith('HEBREW POINT'):
            value = 0.40
    return (doc, position, token), float(value)

