programs.sol:
"""A multilingual lexical signal around 正: right, positive, normal and just.

Use fixed negative pulses for these word pieces, their common translations,
and related orth-/rect- roots. Chinese compounds have a length-based fallback;
Korean 정 and some English pieces distinguish leading spaces. Some weaker
associated/contrasting cues are included, with a positive pulse for 'false'.
A split UTF-8 正 is recognized when the current token completes the character.
This is not a sentence-truth judgment. Unmatched pieces give zero.
"""
READS = ()


def lexical_signal(s):
    if '正' in s:
        if s == '正':
            return -9.5
        if s == '正在':
            return -4.4
        if s == '正是':
            return -5.0
        if s in {'正确', '正确的', '正確', '真正的', '反正', '修正', '矫正'}:
            return -2.1
        if s == '真正':
            return -2.45
        return -3.2 if len(s) <= 2 else -2.5
    if s.strip() == '정':
        return -4.5 if s.startswith(' ') else -2.2
    if s in {'真', '刚', '剛', '整', '规范'}:
        return -0.7
    if s in {'邪', '贞', '陽', '阳', '刚好', '真是'}:
        return -1.05
    w = s.strip().lstrip('_-.(').casefold()
    if w in {'correct', 'orrect', 'corrected', 'correcting',
             'correction', 'corrective'}:
        return -1.75
    if w in {'correctly', 'corrections', 'correctness'}:
        return -1.35
    if w in {'positive', 'positively'}:
        return -1.6 if s == 'positive' else -2.05
    if w == 'positives':
        return -1.2
    if w == 'posit':
        return -0.7 if s.startswith(' ') else -0.4
    if w == 'positivity':
        return -0.56
    if w == 'just':
        return -1.0 if s == 'just' else -1.2
    if w == 'justice':
        return -1.7
    if w == 'normal':
        return -1.2
    if w in {'norm', 'norms', 'normalize', 'normalized',
             'normalization', 'норм'}:
        return -0.8
    if w == 'orth':
        return -2.5 if s[:1].isspace() or s.startswith('Orth') else -0.5
    if w in {'orthogonal', 'orthodox'}:
        return -1.65
    if w == 'rect':
        return -0.85
    if w == 'zheng':
        return -1.9
    if w in {'richtig', 'правильно', 'doğru', 'đúng', 'rightful'}:
        return -1.2
    if w == 'chính':
        return -2.2
    if w == 'đang':
        return -1.6
    if w == '✓':
        return -0.42 if s.startswith(' ') else -0.18
    if w in {'true', 'exactly', 'proper', 'accurate', 'incorrect',
             'incorrectly', 'abnormal', 'normally', 'healthy', 'official'}:
        return -0.3
    if w == 'false':
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    value = lexical_signal(s)
    if '\ufffd' in s and len(prefix.document_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            if prefix.text_prefixes[-1].endswith('正'):
                value = -12.0
    return None, value

programs.haiku:
"""layers.0.mlp.down_proj:2595 -- a 'correct / positive / normal / just' word detector.

What it does: this component writes a strongly NEGATIVE value into the residual stream
exactly when the current token is one of a small family of words meaning "correct",
"positive", "normal" or "just/justice" (in English, and the same idea in Chinese, Korean,
Vietnamese, Russian, German and Turkish). Everywhere else it stays near zero.

The prediction is a lookup on the word the current token spells, not on context:
  * Chinese 正 (zheng, "correct / proper / positive") is the strongest trigger, and any
    compound containing it (正是, 正在, 正常, 正式, 真正, 修正 ...) is strongly negative too.
  * "correct" / "correction" / "correctly" (-1.7); "positive" (-2.0); "normal" (-1.2);
    "just" / "justice" (-1.2); "ortho-" and "rect-" roots (-1.5 and -0.6).
  * Correct/right in other languages (정, 맞, chính, đúng, правильно, richtig, doğru,
    именно, 恰恰, 恰好): about -1.3.
  * Weak: "legit/genuine/rightful" (-0.8), "exactly/perfect/proper/true" (-0.3), 真 (-0.6).
  * Not triggered by: right, exact, fair, good, real, wrong, incorrect (-0.4 only),
    abnormal, normally, adjust, justify, direct.

Values are the average activations the word family gets in sampled text. The program is
stateless: each position is scored from its own token alone.
"""

READS: tuple[str, ...] = ()

ZH_CORRECT = 9.0          # the bare character 正 itself
ZH_COMPOUND = 2.8         # any other token containing 正
FOREIGN_CORRECT = {"정", "맞", "chính", "đúng", "правильно", "richtig", "doğru", "именно", "恰恰", "恰好"}
WEAK_PROPER = {"genuine", "legit", "legitimate", "rightful", "truthful"}
VERY_WEAK = {"exactly", "perfect", "proper", "true"}


def activation_of(token: str) -> float:
    """Predicted activation for one token's text (negative = the component fires)."""
    word = token.lower().strip(" _.(\"'-")
    if "正" in token:
        return -ZH_CORRECT if token.strip() == "正" else -ZH_COMPOUND
    if word in FOREIGN_CORRECT:
        return -1.3
    if word.startswith("incorrect"):
        return -0.4
    if "correct" in word or word.startswith(("correction", "corrective")):
        return -1.7
    if "positiv" in word:
        return -2.0
    if word.startswith("normal") and not word.startswith("normally"):
        return -1.2
    if word.startswith("normaliz") or word == "norm":
        return -0.7
    if word in ("just", "justice", "justices", "justs"):
        return -1.2
    if word.startswith("orth"):
        return -1.5
    if word.startswith("rect"):
        return -0.6
    if word in WEAK_PROPER:
        return -0.8
    if word in VERY_WEAK:
        return -0.3
    if token.strip() == "真":
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    """One position: the activation predicted from the newest token alone."""
    return None, float(activation_of(prefix.token_strings[prefix.position]))

