    'almost': 1.1, 'really': 0.85, 'especially': 0.85,
    'finally': 1.25, 'overall': 0.8, 'mostly': 0.6,
    'entirely': 0.5, 'completely': 0.4, 'totally': 0.6,
    'eventually': 0.45, 'again': 0.25, 'anyway': 0.85,
