    'certainly': 1.2, 'definitely': 1.7, 'necessarily': 1.35,
    'surely': 1.1, 'undoubtedly': 1.3, 'indeed': 0.95,
    'actually': 0.45, 'obviously': 0.45, 'apparently': 0.35,
    'absolutely': 0.5, 'inherently': 0.4, 'therefore': 0.25,
}
# Multilingual frequency, additive, temporal and certainty expressions.
TRANSLATIONS = {
    'sempre': 4.85, 'siempre': 5.3, 'всегда': 5.65,
    'immer': 1.95, 'いつも': 3.5, 'toujours': 5.45,
    'altijd': 3.85, 'luôn': 2.65,
    '总是': 4.1, '總是': 3.7, '常に': 2.2,
    '始终': 2.2, '永远': 2.15, 'やはり': 2.85, 'やっぱり': 2.6,
    'auch': 0.75, 'anche': 0.85, 'también': 0.9,
    'также': 0.65, 'cũng': 0.8, 'także': 1.35,
    'уже': 1.1, 'déjà': 1.3, 'già': 0.95, 'schon': 0.7,
    'encore': 0.85, 'nunca': 0.9, 'ancora': 1.8,
    'まだまだ': 1.65,
    '还是': 1.4, '也是': 1.6, '都是': 1.4, '都': 0.75,
    '一定': 1.25, '一定要': 1.5, '当然': 0.95, '终于': 0.95,
    '仍然': 1.05, '還是': 1.5, '必ず': 2.3,
    'никогда': 1.55, 'обязательно': 1.75, 'souvent': 1.05,
    'également': 0.8, '通常': 0.65,
}
CAPITALIZED = {
    'always': 6.5, 'also': 1.05, 'still': 1.1,
    'usually': 1.9, 'already': 1.8, 'never': 1.1,
    'finally': 0.95, 'sometimes': 1.75, 'often': 1.0,
}
TOTALITY_AND_ASSERTION = {
    'everyone': 0.75, 'everything': 0.5, 'everywhere': 0.9,
    'todos': 0.95, 'todas': 0.8, 'tutti': 0.65, 'tutte': 0.65,
    '总': 1.05, '總': 1.25, '也': 0.35, '是': 0.5, '就是': 0.8,
}
MATERIAL_WORDS = {
    '材': -3.75, '教材': -3.1, '材料': -1.1, '器材': -1.45,
    'material': -0.2, 'materials': -0.5,
}
SCORES = (FREQUENCY | SCOPE_AND_TIME | CERTAINTY | TRANSLATIONS
          | TOTALITY_AND_ASSERTION | MATERIAL_WORDS)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = SCORES.get(lower, 0.0)
    if word[:1].isupper():
