            value = 6.5
        elif lower == 'also':
            value = 1.4
    if token == ' always':
        if previous.lower() in {'is', 'are', "'s", '’s'}:
            value = 8.1
        elif previous.lower() in {'have', 'has', 'can', 'could', 'to'}:
            value = 7.15
        elif previous.lower() in {'not', "'t", '’t'}:
            value = 8.2
    elif token.startswith(' ') and word == lower and lower in {
        'also', 'already', 'still', 'usually', 'often', 'never',
    }:
        before = previous.lower()
        if before in {'is', "'s", '’s'}:
            value += 0.2
        elif before in {'are', 'was', 'were', 'i', 'he', 'she', 'they', 'you'}:
            value += 0.1
        elif before == 'but':
            value -= 0.4
        elif before == 'and':
            value -= 0.15
        elif before in {'have', 'has'} and lower in {'already', 'never'}:
            value -= 0.25
