        value = 0.7
    elif lower == 'course' and previous.lower() == 'of':
        value = 0.75
    elif lower == 'least' and previous.lower() == 'at':
        value = 1.0
    elif word == '.g' and previous.lower() == 'e':
        value = 0.75
    elif word == '.e' and previous == 'i':
        value = 0.7
    if lower == 'yes':
        value = 0.65 if word[:1].isupper() else 0.75
