    "rarely", "seldom", "也是", "还是", "уже", "auch", "anche", "déjà",
}
MODAL = {
    "probably", "maybe", "perhaps", "certainly", "definitely", "surely",
    "necessarily", "really", "indeed", "anyway", "almost", "finally",
    "especially", "such", "just", "least", "undoubtedly", "encore",
}
LOOSE = {
    "actually", "typically", "generally", "normally", "mostly", "eventually",
    "ultimately", "constantly", "forever", "absolutely", "totally", "everyone",
    "everything", "everywhere", "overall", "都是", "就是", "都",
