programs.sol:
"""Approximate a programming-action detector, especially getters and constructors.

Member access, declarations, assignments and recent code punctuation support a
positive response to common method-name verbs. Ordinary prose is mostly zero.
Compound identifiers are weaker. Scope/private-member marks and object receivers
also contribute. State keeps the previous token and a fading syntax cue, reset at
document boundaries. Coarse word classes miss individual identifiers' strengths
and most small background activations.
"""
import re
from functools import lru_cache

READS = ()
# Familiar operation classes, not a vocabulary-ID lookup.
GROUPS = (
    (3.35, 'get'),
    (2.9, 'create construct generate build'),
    (2.0, 'load parse make encode deserialize inflate'),
    (1.8, 'set'),
    (1.45, 'put find read render apply execute save resolve clone init is from '
     'validate normalize convert calculate compute evaluate retrieve'),
    (0.9, 'add remove run clear update write of to format restore send check '
     'verify equals contains can has on derive cast unwrap'),
    (0.5, 'next call query register delete start show notify compile strip '
     'handle request extract draw process open translate expand count split'),
    (0.28, 'test append push println'),
)
VERBS = {w: s for s, words in GROUPS for w in words.split()}
DECLARATIONS = set('def function func fn void int long short char bool boolean '
                   'float double string String Object auto public private static'.split())
FUNCTION_WORDS = set('of to from is has can on'.split())
MARKS = {'::': 0.85, '->': 0.85, '._': 1.1, '.__': 0.7,
         '().': 0.75, '()).': 0.4, '?.': 0.4, ' _': 0.36,
         '_->': 1.1, '()->': 0.85, '>::': 1.05}

@lru_cache(maxsize=16384)
def parts(token):
    m = re.fullmatch(r'([^A-Za-z]*)([A-Za-z][A-Za-z0-9_]*)', token)
    if not m:
        return '', '', '', False
    lead, word = m.groups()
    first = re.match(r'[A-Z]?[a-z]+|[A-Z]+(?![a-z])', word)
    head = first[0].lower() if first else ''
    return lead, word, head, word.lower() != head


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, code = '', 0.0
    else:
        _, previous, code = carry
    lead, word, head, compound = parts(token)
    old = previous.strip()
    attached = bool(previous) and not previous[-1].isspace()
    indented = previous.isspace() and (len(previous.rsplit('\n', 1)[-1]) > 1
                                      or '\t' in previous)
    typed = old in DECLARATIONS or (code > 0.1 and (
        old[-1:] in {'>', ']'} or (len(old) > 1 and old[:1].isupper())))
    member = lead == '.' or (not lead and attached and
                             old.endswith(('::', '->', '.')))
    factor = 0.85 if compound else 0.03
    if lead == '.':
        factor = 1.0
    elif not lead and attached and old.endswith(('::', '->', '.')):
        factor = (1.4 if old.endswith('::') else
                  1.15 if old.endswith('->') else 0.95)
    elif head == 'construct' and old in {'__', '._', '_'}:
        factor = 1.3
    elif typed and lead.isspace():
        factor = 0.85
    elif old in {'=', ':=', 'return', 'throw', 'await'}:
        factor = 0.66
    elif indented or old in {'{', '}', '>', '[]'} or code > 0.6:
        factor = max(factor, 0.5)
    elif lead and not lead.isspace():
        factor = max(factor, 0.35)
    elif not lead and attached:
        factor = 0.35 if not old[-1].isalnum() else (0.28 if word[:1].isupper() else 0.)
    value = MARKS.get(token, -0.003)
    if head in VERBS:
        shape = (0.42 if head == 'get' else 0.35) if compound else 1.0
        shape *= 0.36 if word.isupper() else (0.74 if word[:1].isupper() else 1.)
        value = VERBS[head] * shape * factor
        if lead == '.' and head == 'get':
            receiver = old.lstrip('(')
            value *= 1.3 if receiver == 'this' else (
                0.75 if len(receiver) == 1 and receiver.isalpha() else 1.0)
        if head in FUNCTION_WORDS and not compound and not member:
            value = 0.0
    elif head == 'new':
        if compound:
            value = 2.4 if word.lower() == 'newinstance' else 0.15
        elif old.endswith('::') or old == 'fn':
            value = 2.65
        elif old in {'=', ':=', 'return', 'throw'}:
            value = 1.65
        elif typed or indented or (code > 0.1 and
                                   old.endswith(('(', ',', '||', '->'))):
            value = 1.3
        elif code > 0.5 or lead.strip():
            value = 1.05
        else:
            value = 0.2
        if not compound and word == 'New' and lead.isspace():
            value = 0.15
    elif word in {'this', 'super'}:
        if indented or old in {'return', '=', '{'}:
            value = 0.95
        elif lead.strip() or (not lead and attached):
            value = 0.6
        else:
            value = 0.45 if code > 0.6 else 0.0
    elif word == 'await':
        value = 0.56
    elif head in {'print', 'assert'} and lead != '.' and not compound:
        value = -0.12
    code *= 0.88
    if any(c in token for c in '=;{}') or token in {'::', '->'}:
        code = min(1.0, code + 0.4)
