programs.haiku:
"""layers.0.mlp.down_proj:2597 -- the "method-name verb" detector.

What it responds to, in source code (not English prose):
  * the member-access operators `::`, `->`, `._`, `().` (they open a method or
    field name), moderately;
  * the verb that starts a method or function name, right after an access
    operator (`.get`, `.create`, `::new`, `->set`) -- strongly; getter/factory
    verbs (get, create, generate, construct, load, parse, make, build) most of
    all, other verbs (new, set, find, put, init, read, add, ...) less;
  * the same verbs when they start a declared or called name in code
    (`public int get`, `= new Foo`, `function load`), at a lower level.
Everywhere else (prose, other words, dotted names like `.name`) it predicts ~0.

Plain-language summary: "a programming verb that begins a method call".
"""
import re

READS = ()

STRONG = ("get", "create", "generate", "construct", "load", "parse", "make", "build")
MEDIUM = ("new", "set", "find", "put", "init", "read", "write", "update", "remove", "add", "run")
ACCESSORS = ("::", "->", "._", "().")
DECLARATION_WORDS = {"function", "void", "int", "long", "String", "double", "bool", "boolean",
                     "static", "public", "private", "protected", "fn", "def", "func", "async",
                     "pub", "char", "float", "var", "const", "throw", "return", "new", "="}
CODE_SIGNS = re.compile(r"[(){};=<>\[\]]|::|->|\.\w|_\w|\bfn\b|\bdef\b|\bpublic\b|\bvoid\b"
                        r"|\bint\b|\breturn\b|\bfunc\b")


def verb_of(word):
    """The verb opening a camelCase word: 'get' in 'get', 'getItem', 'Get'."""
    for verb in STRONG + MEDIUM:
        if word.lower().startswith(verb) and (len(word) == len(verb) or word[len(verb)].isupper()):
            return verb
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token in ACCESSORS:
        return carry, 0.85
    verb = verb_of(token.lstrip(" .:->_("))
    if verb is None:
        return carry, 0.0
    strong = verb in STRONG
    if token.startswith((".", "::", "->")) or before in ACCESSORS:
        return carry, (2.4 if strong else 1.2)
    in_code = bool(CODE_SIGNS.search("".join(prefix.token_strings[-3:-1])))
    if in_code or before.strip() in DECLARATION_WORDS:
        return carry, (1.6 if strong else 0.8)
    return carry, (0.2 if strong else 0.1)

