programs.sol:
"""A single capital I and short uppercase token chunks.

Length, vowel pattern, and familiar computing initialisms set the response
height. Roman numerals and the prose words OF/THE respond less. Uppercase
continuations and recent all-capital text are suppressed; punctuation helps
distinguish separate abbreviations from uppercase prose. pH and short mixed-
case forms have small separate responses. Casing history resets per document.
"""
from functools import lru_cache
import string

READS = ()
LETTERS = frozenset(string.ascii_letters)
LENGTH_LEVEL = (0.0, 0.0, 0.85, 0.65, 0.53, 0.36, 0.33, 0.27, 0.18)
ROMAN_NUMERALS = frozenset(('II III IV VI VII VIII IX XI XII XIII XIV XV '
                            'XVI XVII XVIII XIX XX').split())

COMPUTING_INITIALISMS = frozenset('''
    IT ID IP OS API URL URI HTML HTTP HTTPS SQL JSON XML CPU GPU USB
    RAM ROM DNS TCP UDP SSL SSH CLI GUI IDE JVM
'''.split())


@lru_cache(maxsize=8192)
def shape(token):
    word = token.strip()
    letters = ''.join(c for c in token if c in LETTERS)
    upper = sum(c.isupper() for c in letters)
    return word, letters, upper


def abbreviation_level(core):
    n = len(core)
    value = LENGTH_LEVEL[min(n, 8)]
    vowels = sum(c in 'AEIOU' for c in core)
    if n == 2 and core[0] in 'AEIOU':
        value += 0.23
        if core[0] in 'IO' and vowels == 1:
            value += 0.30
    elif n == 3 and core[0] in 'AEIOU':
        value += 0.12
    elif n == 4 and vowels == 0:
        value += 0.33
    if core in ROMAN_NUMERALS:
        value = 0.72 if n == 2 else 0.15
        if core == 'II':
            value = 0.30
    if core in COMPUTING_INITIALISMS:
        value = 1.65 if n == 2 else 1.05
        if core == 'IT':
            value = 2.20
    if core in ('OF', 'THE'):
        value = 0.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', '', ())
    _, previous, last_nonspace, history = carry
    token = prefix.token_strings[-1]
    word, letters, upper = shape(token)
    total = sum(n for u, n in history)
    capitals = sum(u for u, n in history)
    capital_passage = total >= 5 and capitals > 0.7 * total
    continuation = bool(token[:1].isalpha() and previous.isupper())
    last_chunk_was_caps = False
    for u, n in reversed(history):
        if n:
            last_chunk_was_caps = n >= 2 and u == n
            break

    # Strip punctuation attached to a short abbreviation, but not numbers.
    plain = word.strip(string.punctuation + '“”‘’')
    plural = len(plain) >= 3 and plain.endswith('s') and plain[:-1].isupper()
    core = plain[:-1] if plural else plain
    value = 0.0
    if core.isascii() and core.isalpha() and core.isupper():
        n = len(core)
        if core == 'I':
            value = 1.07 if token[:1].isspace() else 0.95
            if first:
                value = 1.36
            else:
                if last_chunk_was_caps:
                    value *= 0.87
                if capital_passage:
                    value *= 0.78
        elif core == 'O':
            value = 0.18
        elif n == 1:
            value = -0.015
        elif not first:
            value = abbreviation_level(core)
            punctuation_boundary = plain != word or not last_nonspace.isalpha()
            if last_chunk_was_caps:
                value *= 0.75 if punctuation_boundary else 0.15
            if capital_passage:
                value *= 0.80 if punctuation_boundary and last_chunk_was_caps else 0.40
        if continuation:
            value = -0.08 if n > 1 else -0.05
        if plain != word:
            value *= 0.7
        if plural:
            value *= 0.8
    elif plain == 'pH':
        value = 0.50
    elif (plain.isascii() and plain.isalpha() and upper >= 2
          and len(plain) <= 5):
        value = 0.30

    history = (history + ((upper, len(letters)),))[-8:]
    if token.rstrip():
        last_nonspace = token.rstrip()[-1]
    return (doc, token[-1:], last_nonspace, history), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2600.

The component is nearly silent on ordinary text. It turns negative on a few
kinds of token, and the program scores each token by its own text:

  * chat-template and tool markup: <|im_end|> most of all, then <|im_start|>
    and the think / tool-call tags;
  * Latin-alphabet letters with diacritics (é, ö, ß, ſ, ...), about -1.3;
  * superscript and other non-ASCII digits, about -1.5;
  * Greek letters, about -0.4;
  * dashes, mathematical and other symbols (—, −, ×, →, ✓, °), about -0.6 to -0.9;
  * the Unicode replacement character, about -0.2.

It is zero for ASCII text, CJK, Cyrillic, Arabic, kana, hangul, and for
punctuation such as 。，、, which the component ignores.
"""

import unicodedata

READS = ()

MARKUP = {
    "<|im_end|>": -3.9,
    "<|im_start|>": -1.0,
    "<think>": -2.0,
    "</think>": -2.8,
    "<tool_call>": -1.8,
    "</tool_call>": -1.7,
    "<tool_response>": -1.3,
    "</tool_response>": -1.8,
}


def value(s):
    if s in MARKUP:
        return MARKUP[s]
    t = s.strip()
    if not t or t.isascii():
        return 0.0
    first = t[0]
    name = unicodedata.name(first, "")
    cat = unicodedata.category(first)
    if name.startswith("LATIN"):
        return -1.35
    if name.startswith("GREEK"):
        return -0.36
    if cat in ("No", "Nd") or name.startswith("SUPERSCRIPT"):
        return -1.4
    if first == "�":
        return -0.2
    if cat == "Pd":
        return -0.6
    if cat in ("Sm", "So"):
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    return carry, value(prefix.token_strings[-1])

programs.luna:
"""Marks uncommon non-ASCII writing and explicit assistant-turn endings.

The strongest response is a negative one to accented or otherwise unusual
letters, marks, and symbols; ordinary CJK letters are not treated as unusual.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "<|im_end|>" in token:
        return None, -3.7

    # CJK script characters are common writing, not the rare typography this
    # simple rule is intended to mark.
    for char in token:
        if ord(char) < 128:
            continue
        name = unicodedata.name(char, "")
        if any(script in name for script in (
            "CJK", "HIRAGANA", "KATAKANA", "HANGUL", "IDEOGRAPHIC", "FULLWIDTH",
        )):
            continue
        category = unicodedata.category(char)
        if char == "\ufffd":
            return None, -0.3
        if category.startswith("L"):
            return None, -0.3
        if category.startswith("M"):
            return None, -0.2
        if category.startswith(("P", "S", "N")):
            return None, -0.3
        return None, -0.2
    return None, 0.0

programs.sol:
"""A negative lexical detector centered on 'present'.

Its inflections, 'presence', 'president', 'represent', and common cognates
have distinct strengths. Split endings and immediately following articles or
prepositions can echo the response. 'Present' is stronger early in a document,
and weaker after 'at', 'are', 'were', or 'be'. Other tokens stay quiet.
"""
from math import exp

READS = ()
PRESENT = {
    'present': -6.0, 'presents': -5.4, 'presented': -4.2,
    'presenting': -4.6, 'presentation': -2.7, 'presentations': -2.5,
    'presenter': -2.1, 'presently': -1.6,
}
ENDINGS = {'ed': -3.7, 'es': -3.0, 's': -3.0, 'ing': -4.2,
           'ly': -2.8, 'ent': -2.3, 'ation': -1.0, 'ations': -1.0}
CONNECTORS = {'a': .75, 'an': .65, 'the': .42, 'in': .4,
              'at': .45, 'to': .25, 'by': .25, 'on': .2}
# Words for presenting, representing, or proposing in Chinese.
CHINESE = {'代表', '提出', '呈现', '出席', '献'}


def response(token):
    raw = token.strip()
    word = raw.lower().lstrip('_-.')
    if word in PRESENT:
        value = PRESENT[word]
        return value * .5 if raw.isupper() else value
    if word in {'presence', 'présence'}:
        return -2.18
    if word.startswith('presiden'):
        return (-.53 if word.endswith('tial') else
                -.7 if word.endswith('cy') else
                -1.3 if word.endswith('ts') else -1.96)
    if word.startswith(('represent', 'représent')):
        return (-1.8 if word.endswith('ed') else
                -1.1 if 'ation' in word or 'ative' in word else -1.48)
    if word in {'présent', 'prés'}:
        return -3.5 if word == 'présent' else -1.8
    if word.startswith(('presenta', 'presente', 'présente', 'apresent')):
        return -2.7
    if word.startswith(('представ', 'настоящ')) or word in CHINESE:
        return -1.4
    if word in {'現', '现'}:
        return -.9
    if word in {'absence', 'absent'}:
        return -1.04 if word == 'absence' else -1.55
    if word.startswith('propos'):
        return -.85
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    word = token.strip().lower().lstrip('_-.')
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    value = response(token)
    if word == 'present':
        value -= .9 * exp(-position / 55)
        if previous == 'the':
            value -= .2
        elif previous == 'at':
            value += .85
        elif previous in {'are', 'were', 'be'}:
            value += .5
    if not token[:1].isspace():
        if word == 'present' and previous == 're':
            value = -3.0
        elif word == 'resent':
            value = -3.6
        elif word == 'resents':
            value = -2.0 if previous == 'rep' else -4.1
        elif word == 'sent' and previous == 'pre':
            value = -5.6
        elif previous in {'present', 'présent'}:
            value += ENDINGS.get(word, 0.0)
        elif previous.startswith(('represent', 'représent')):
            value += {'ed': -1.5, 'ing': -1.3, 'ation': -.6,
                      'ations': -.65, 'ent': -1.25}.get(word, 0.0)
    if token[:1].isspace() and word == 'of':
        if previous.startswith(('presiden', 'represent')) or previous == 'presence':
            value -= .54 * abs(response(previous))
        elif previous == 'absence':
            value -= .85
    if previous in {'present', 'presents', 'presented', 'presenting',
                    'represent', 'represents', 'represented', 'representing'}:
        strength = 1.0 if previous.startswith('present') else .65
        value -= strength * CONNECTORS.get(word, 0.0)
    return (doc, word, position), float(value)

