            return None, -4.1
        if word.startswith("presently"):
            return None, -1.4
        if word.startswith(("presentation", "presenter")):
            return None, -2.6
        if word.startswith("presents"):
            return None, -5.2
        return None, -6.2
    if "present" in word:
