    "suggest", "suggests", "suggested", "suggesting",
    "indicate", "indicates", "indicated", "indicating",
    "show", "shows", "showed", "shown", "showing",
    "found", "revealed", "reveal", "reported", "observed", "demonstrated", "conclude",
