programs.haiku:
"""layers.0.mlp.down_proj:2610 -- "second half of a split word" detector.

What it does: the component fires on the second token of a word that the tokenizer
split into two pieces, when the first piece is a short opening fragment (a leading
space plus 1-3 letters, e.g. " Gr" + "anta", " Br" + "andy", " Sk" + "olars") and the
second piece is a short ending with no leading space. The model is spelling out an
unfamiliar word across two tokens. The strength drops as the opener gets longer, and
is small for a 2-letter ending. Third and later pieces, and ordinary words, are ~0.

Measured on 512 training rows: the strongest case (opener of 1-2 letters, ending of
3-5 letters) averages about +0.15; opener of 3 letters about +0.08.
"""

READS = ()


def _letters(s):
    return s.strip().isalpha()


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return None, 0.0
    cur = prefix.token_strings[t]
    prev = prefix.token_strings[t - 1]
    if cur.startswith(" ") or not _letters(cur):
        return None, 0.0
    if not (prev.startswith(" ") and _letters(prev)):
        return None, 0.0          # the first piece must itself start a word
    opener = len(prev.strip())    # letters in the opening piece
    ending = len(cur)             # letters in the second piece
    if opener > 3:
        return None, 0.0
    if ending >= 3:
        return None, (0.15 if opener <= 2 else 0.08)
    if ending == 2:
        return None, 0.03
    return None, 0.0

programs.sol:
"""A detector for six and a few familiar ways of referring to it.

The digit (also fullwidth) and English six-family words receive strong
positive activations. Chinese 六 is stronger; June, the sixth month, is weaker.
Unrelated tokens receive a small negative baseline.
"""
READS = ()

SIX_WORDS = {'six', 'sixth', 'sixty'}
TEEN_WORDS = {'sixteen', 'sixteenth'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.lower()
    value = -0.0015
    if token in {'6', '６'}:
        value = 0.68
    elif token == '六':
        value = 0.95
    elif word in SIX_WORDS:
        value = 0.72
    elif word in TEEN_WORDS:
        value = 0.44
    elif word == 'june':
        value = 0.43
    return None, value

programs.luna:
"""Respond to tokens that name or write the number six.

In corpus samples the ASCII digit 6 is by far the clearest trigger. Six-words,
other six-valued numerals, and June also tend to give positive responses. The
constants are typical activations; this deliberately ignores context variation.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.lower()

    if word == "june":
        return None, 0.45
    if word == "vi":  # Roman numeral six
        return None, 0.23
    if "six" in word:
        return None, 0.70
    if token == "六":
        return None, 0.99
    if len(token) == 1:
        try:
            if unicodedata.numeric(token) == 6:
                return None, 0.68
        except (TypeError, ValueError):
            pass
    return None, 0.0

programs.haiku:
"""Official-action verbs (layer 0, MLP down-projection, component 2613).

What it does: this component turns on for words that say something formal is being
done by an institution: establishing, enacting, signing, passing, publishing, announcing,
implementing, approving, appointing, launching, ending or scheduling laws, bodies,
policies, events or projects. Examples: "was [established]", "[signed] the agreement",
"Congress [passed] the", "set [up]", "carry [out]", "[实施]", "[出台]", "[公布]".

Plain-language rule, as a program:
  - a past-tense or participle form of such a verb (established, enacted, passed,
    signed, held, ended) gives a strong value;
  - a base form, -ing form, or the related noun (sign, pass, election, construction)
    gives a weaker value;
  - the same official-action verbs written in Chinese give a strong value;
  - "up" or "out" right after set/setting/carry/carried gives the strongest value;
  - a function word (the, of, a, its, ...) right after a strong verb gets a small value.
Everything else is 0. Values are roughly the component's typical activation (in units of
its own activation scale).
"""
READS = ()

# English verb stems; a token matches if it starts with one (covers inflections)
STEMS = (
    "establish", "enact", "ratif", "abolish", "repeal", "amend", "announc",
    "publish", "implement", "approv", "appoint", "launch", "adopt", "conduct",
    "impose", "reform", "schedul", "conclud", "cancel", "terminat", "suspend",
    "initiat", "commenc", "finaliz", "renam", "reopen", "inaugurat", "introduc",
)
# irregular or short past forms of formal verbs
PAST = {
    "signed", "passed", "issued", "released", "filed", "elected", "founded", "held",
    "opened", "ended", "began", "begun", "ceased", "sworn", "launched",
}
# bare forms and nouns of formal acts
BASE = {
    "sign", "signs", "signing", "pass", "passes", "passing", "release", "releases",
    "elect", "election", "elections", "construction", "publication", "completion",
    "adoption", "legislation", "schedule", "schedules", "ceremony", "conduct", "launch",
}
# Chinese verbs of official action: enact, implement, set up, announce, hold, end, ...
ZH = set(
    "实施 实行 出台 设立 召开 公布 签订 组建 完善 生效 发行 举行 制定 开展 "
    "取消 启动 建立 落实 成立 宣布 发布 批准 推出 采取 确定 通过 建设 推进 "
    "加强 改革 颁布 举办 开放 深化 健全 巩固 强化 结束 完成 形成 加快 推动 "
    "废除 停止 解除 进行 执行 实现 推行 改善 优化 规范 采用 公告 设置 建成".split()
)
SETS = {"set", "setting", "sets", "carry", "carried", "carrying", "carries"}
FUNC = {"the", "of", "a", "an", "its", "their", "this", "that", "to"}


def level(tok):
    """How strongly a token is a formal-action word: 0.6, 0.3, or 0."""
    w = tok.lower()
    if tok in ZH:
        return 0.6
    if w in PAST or (w.startswith(STEMS) and w.endswith("ed")):
        return 0.6
    if w.startswith(STEMS) or w in BASE:
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    w = tok.lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if w in ("up", "out"):
        return None, (0.8 if prev in SETS else 0.0)
    if level(tok):
        return None, level(tok)
    if w in FUNC and level(prev) >= 0.6:
        return None, 0.2
    return None, 0.0

programs.sol:
"""Partial lexical explanation: a negative systems-and-equipment signal.

Hardware modifiers strengthen 'system'; other senses weaken it. Devices,
displays, equipment descriptions and technology names respond negatively.
Explicit thought/tool delimiters have smaller negative responses. Everything else is
zero, leaving the component's diffuse, small lexical effects unexplained.
Only the last 64 characters of the current document supply context.
"""
import re

READS = ()
HARDWARE = set('''speaker speakers sound audio loudspeaker stereo binocular
    microphone ignition cooling braking stoplight alarm driving autonomous
    iot drone drones surveillance sensing safety bluetooth gaming
    entertainment'''.split())
ENGINEERING = set('''exhaust transmission computer optical electronic digital
    electrical mechanical navigation sensor sensors circuit emulation heating
    charging power steering ventilation display projection integrated'''.split())
NON_EQUIPMENT_SYSTEMS = set('''operating immune metric coordinate linear
    file equation equations mathematical political social legal banking retirement'''.split())
SYSTEMS = {'系统', '系統', '시스템', 'систем', 'система', 'системы', 'истем'}
DEVICES = {'设备', '設備', '装置', '设施', '基础设施'}
TECHNOLOGY_NAMES = set('''headset headsets headphones projector bluetooth
    playstation nintendo garmin siri sdk keycode'''.split())
EQUIPMENT = set('''equipment apparatus furniture cabinets cabinet glasses
    wheelchair amenities decor interiors electronic electronics'''.split())
EQUIPMENT_DESCRIPTIONS = set('''equipped installation installations mounting
    installing integrated integration interactive'''.split())
BOUNDARIES = {'</think>': -0.23, '<tool_call>': -0.10,
              '<tool_response>': -0.07}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('._/-(')
    context = set(re.findall(r'[a-z]+', recent.lower()))
    hardware = bool(context & HARDWARE)
    engineering = bool(context & ENGINEERING)
    value = BOUNDARIES.get(token, 0.0)

    if word in {'system', 'systems', 'ystem'}:
        value = -0.54 if word == 'systems' else -0.42
        if hardware:
            value -= 0.53
        elif engineering:
            value -= 0.28
        elif context & NON_EQUIPMENT_SYSTEMS:
            value += 0.21
        if 'using' in context and token.strip() == 'System':
            value = -0.60
        elif token.startswith('\t'):
            value = -0.21
        elif token == token.strip() and not hardware and not engineering:
            value += 0.06
    elif word in SYSTEMS or '系统' in word:
        value = -0.57
    elif word in {'device', 'devices'}:
        value = -0.42 - 0.15 * (hardware or engineering)
        if token == token.strip():
            value += 0.15
    elif word in DEVICES:
        value = -0.47
    elif word == 'mounted':
        value = -0.60
    elif word == 'installed':
        value = -0.30
    elif word in EQUIPMENT_DESCRIPTIONS:
        value = -0.22
    elif word in {'display', 'displays', 'displayed', 'displaying'}:
        value = -0.32 if token.startswith(' ') else -0.10
        if hardware or context & {'lcd', 'crystal'}:
            value -= 0.22
    elif word == 'panel' and 'touch' in context:
        value = -0.44
    elif word == 'console' and context & {'game', 'gaming', 'video'}:
        value = -0.55
    elif word in TECHNOLOGY_NAMES:
        value = -0.34 - 0.20 * hardware
    elif (recent + token).lower().endswith('joystick'):
        value = -0.50
    elif word in EQUIPMENT:
        value = -0.24
    return (doc, (recent + token)[-64:]), float(value)

programs.luna:
"""Predict negative activity on words naming systems and technical objects.

The strongest cues are literal names such as “system” and “device”; a smaller
set covers equipment, displays, and related technology. Other tokens get zero.
"""

import unicodedata

READS = ()

SYSTEMS = {"system", "systems", "систем", "системы", "系统", "系統"}
DEVICES = {"device", "devices", "equipment"}
EQUIPMENT = {
    "headset", "headsets", "keyboard", "keyboards", "display", "displays",
    "screen", "panel", "sensor", "console", "camera", "cabinet",
    "cabinets", "mount", "mounted", "installed", "equipped", "feature",
    "hardware", "machine", "machines", "computer", "server", "network",
}
TECH_TERMS = {
    "lighting", "strip", "strips", "virtual", "vr", "tv", "lidar",
    "garmin", "siri", "neurology", "柜",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip()
    while word and unicodedata.category(word[0]).startswith(("P", "S")):
        word = word[1:]
    while word and unicodedata.category(word[-1]).startswith(("P", "S")):
        word = word[:-1]

    if word in SYSTEMS or word in DEVICES:
        return None, -0.5
    if word in EQUIPMENT:
        return None, -0.35
    if word in TECH_TERMS:
        return None, -0.3
    return None, 0.0

programs.sol:
"""Detect short 'aw' spellings, strongest in raw, law and the fragment aw.

Longer aw words are weaker. Related short w/av spellings and legal vocabulary
have smaller responses. A law(s)-of phrase continues the response onto 'of'.
These are spelling/word rules, not a dictionary of token ids.
"""

READS = ()


def bare(token):
    return token.strip().strip('._/\\-()[]{}<>:;,\"\'')


def response(token):
    spelling = bare(token)
    word = spelling.lower()
    if word == 'raw':
        return 6.7
    if word in {'law', 'ław'}:
        return 4.5 if spelling == 'law' and token.startswith(' ') else 4.9
    if word == 'aw':
        if spelling == 'Aw':
            return 3.8
        return 4.3 if token.startswith(' ') else 5.3
    if word == 'awa':
        return 3.8
    if word == 'aws':
        return 3.4 if token.startswith(' ') or spelling.isupper() else 4.7
    if word == 'laws':
        return 3.2
    if word.startswith(('withdraw', 'unlaw', 'outlaw')):
        return 0.6
    if word.endswith('aw'):
        if word in {'draw', 'saw', 'shaw', 'straw', 'seaw'}:
            if word == 'shaw':
                return 2.5
            if spelling == 'Saw':
                return 3.0
            return 1.6
        if word == 'flaw':
            return 0.6
        return 4.0 if len(word) <= 5 else 1.0
    if 'aw' in word:
        if word.startswith(('away', 'aware', 'await', 'lawsuit')):
            return 0.2
        if len(word) == 3:
            return 2.8 if word != 'awk' else 1.5
        return 2.0 if len(word) == 4 else 0.9
    if word.endswith('ав'):
        return max(0.4, 2.8 - 0.5 * len(word))
    if word == 'яв':
        return 1.5
    if word.endswith('av') and len(word) <= 4:
        return 0.9
    if word.endswith('rw'):
        return 1.3 if len(word) <= 3 else 0.0
    if word.endswith('ew') and len(word) <= 4 and word not in {
        'new', 'few', 'knew', 'grew', 'view'
    }:
        return 0.45 if word == 'ew' else 0.85
    if word in {'row', 'rows', 'crow', 'prow', 'tow', 'snow', 'hollow', 'marrow'}:
        return 1.05 if word == 'row' else 0.8
    if word in {'legal', 'attorney', 'закон', '依法', '立法'}:
        return 1.0
    if word == '法':
        return 1.2
    if word == '法律':
        return 2.6
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    value = response(token)
    if carry is not None and carry[0] == document:
        previous = carry[1]
        if token == ' of' and previous in {'law', 'laws'}:
            value = 2.8 if previous == 'law' else 1.8
    return (document, bare(token).lower()), value

programs.haiku:
"""layers.0.mlp.down_proj:2615, a "law / aw-sound" word detector.

What the component does: when the current token is the word "law" (or "raw", "aw", "jaw",
"paw"), or a word built on the "aw" vowel sound (/ɔː/ as in "law"), it writes a strong
signal into the residual stream. Weaker signals come from longer words that contain the
same sound ("saw", "draw", "dawn", "award") and from law-related words ("lawyer", "legal",
法律, ав). Everything else gets roughly zero.

It is a spelling detector: it looks only at the newest token, with no memory of earlier
tokens and no reading of context. Case, leading space and surrounding punctuation are
ignored, so " Law", "LAW" and "-law" all count.

The values are the average activations measured on training text, in three tiers:
  raw                                  6.5
  law, aw, jaw, paw, ław               5.0
  laws, aws, awa, awi, awe, awn, awy, awl, lawn   3.0
  saw, draw, drawn, drawing, draws, dawn, award(s), lawyer(s), legal, 法律, 法, ав, av   1.2
  anything else                        0.0
"""

READS = ()

RAW = {"raw"}
CORE = {"law", "aw", "jaw", "paw", "ław"}
PLURAL = {"laws", "aws", "awa", "awi", "awe", "awn", "awy", "awl", "lawn"}
WEAK = {
    "saw", "draw", "drawn", "drawing", "draws", "dawn", "award", "awards",
    "lawyer", "lawyers", "legal", "法律", "法", "ав", "av",
}  # fmt: skip


def _word(token):
    """The token as a bare lowercase word: no case, space or surrounding punctuation."""
    return token.strip().lower().strip("-_./()\"' ")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    if word in RAW:
        value = 6.5
    elif word in CORE:
        value = 5.0
    elif word in PLURAL:
        value = 3.0
    elif word in WEAK:
        value = 1.2
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A partial lexical explanation: Thai script, Indonesian, and Java imports.

Thai consonant-led pieces and preposed vowels are stronger than trailing
vowel/tone fragments. The nominalizers ความ and การ are stronger still.
Indonesian common words, demonstratives and
word-building prefixes are positive. A decaying Indonesian-language cue helps
disambiguate short prefixes. Southeast Asian names also receive a response.
Most other text is predicted as zero; other lexical effects are omitted.
"""
import re

READS = ()

DEMONSTRATIVES = {'ini': 1.35, 'itu': 1.20, 'tersebut': 1.58}
INDONESIAN_WORDS = set('''saya kita kami mereka anda dalam dengan kepada pada tentang
    oleh seperti sebagai dan atau karena jika maka namun juga akan telah sudah
    bisa dapat adalah tidak harus beberapa banyak besar semua hanya satu dari
    untuk menjadi merupakan tahun nilai secara sebuah setelah sebelum saat
    waktu selama lain bagi agar lebih bahwa ingin mungkin tetapi hingga utama'''.split())
DISTINCTIVE_PREFIXES = {'meng', 'meny', 'peng', 'pemb'}
CUES = INDONESIAN_WORDS | set(DEMONSTRATIVES) | DISTINCTIVE_PREFIXES | {'yang'}
SHORT_FORMS = {
    'di': (0.02, 1.08), 'ke': (0.22, 0.76),
    'ber': (0.01, 0.76), 'ter': (0.04, 0.70),
    'per': (-0.07, 0.48), 'se': (0.0, 0.22), 'hal': (0.05, 0.68),
}
REGION = {'malaysia', 'malaysian', 'philippines', 'philippine', 'filipino',
          'thailand', 'singapore', 'singaporean', 'bali', 'jakarta',
          '马来西亚', '菲律宾', '泰国', '新加坡'}
INDONESIA = {'indonesia', 'indonesian', 'indonesians', 'onesia', '印度尼西亚'}


def thai_value(word):
    if word in {'ความ', 'การ'}:  # nominalization of qualities and actions
        return 1.20 if word == 'ความ' else 0.80
    first = word[0]
    if '\u0e01' <= first <= '\u0e2e' or first in 'เแโใไ':
        return 0.46
    return 0.14  # trailing vowels and tone marks


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    _, language, last_nonspace, word_tail = (
        (doc, 0.0, '', '') if reset else carry
    )
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    boundary = token[:1].isspace() or reset
    # Finish words split across tokens before interpreting the new token.
    chunks = re.split(r'[^A-Za-z]+', word_tail + token)
    for completed in chunks[:-1]:
        if completed.lower() in CUES and completed not in {'Dan', 'Yang'}:
            language = 1.0
    word_tail = chunks[-1][-32:]
    value = 0.0
    if any('\u0e01' <= c <= '\u0e5b' for c in word):
        value = thai_value(word)
    elif lower in INDONESIA:
        value = 0.93
    elif lower in REGION:
        value = 0.60
    elif word == 'import':
        value = 0.68 if token == word and last_nonspace == ';' else 0.12
    elif word == 'Yang':
        value = 0.18 + 0.68 * language
    elif word == 'Ini':
        value = 0.95
    elif word == 'asyarakat':  # fragment of masyarakat, society
        value = 0.93
    elif boundary:
        if lower in DEMONSTRATIVES:
            value = DEMONSTRATIVES[lower]
        elif lower == 'yang' or lower in DISTINCTIVE_PREFIXES:
            value = 1.15 if lower == 'pemb' else 0.85
            if not word.islower():
                value = 0.15 + value * language
        elif lower in INDONESIAN_WORDS:
            value = 0.48 if word.islower() else 0.15 + 0.40 * language
        elif lower in SHORT_FORMS:
            base, gain = SHORT_FORMS[lower]
            value = base + gain * language
        elif lower.startswith(('meng', 'meny', 'mem', 'men', 'pem', 'pen',
                               'ber', 'ter', 'di')):
            value = 0.80 * language
        elif lower.startswith(('mel', 'mer', 'ke', 'pe')):
            value = 0.55 * language
    elif word == 'nya':  # possessive/pronominal suffix
        value = 0.05 + 0.52 * language
    language *= 0.98
    if (boundary and word.islower() and lower in CUES) or word == 'Indonesia':
        language = 1.0
    if word:
        last_nonspace = word[-1]
    return (doc, language, last_nonspace, word_tail), value

programs.luna:
"""A small lexical sketch of a rare early-layer feature: formal connective and
math-writing tokens tend to give it a negative activation. This is only a
coarse token-class predictor, not a parser or a mathematical checker."""
READS = ()

# Common connective and notation words seen at definitions, explanations,
# and proofs. Values are deliberately modest because the feature is sparse.
CONNECTIVES = {
    'that': -0.38, 'requiring': -0.28, 'condition': -0.28,
    'setting': -0.25, 'sequence': -0.40,
}
NOTATION = {
    ':': -0.30, '∩': -0.30, 'inf': -0.28, 'spaces': -0.32,
    'subgroup': -0.38, 'cellular': -0.28, 'f': -0.24,
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.25 * CONNECTIVES.get(word, NOTATION.get(word, 0.0))
    return None, float(value)

programs.sol:
"""A local lexical signal for visiting, accessing and inspecting.

Forms of 'visit' dominate; access and the 'vis' word fragment are next.
Related sight, travel, consultation and revision words give weaker values,
as do a few other 'vis' spellings. Several translations are included. Split visit-words fire on their second piece too.
Signal also appears on 'to', 'at' and determiners in short motion/sight phrases.
This intentionally leaves most unrelated token-specific variation unexplained.
"""

READS = ()

# Visit, travel and inspection words or word pieces in other languages.
VISITING = {
    "访问": 5.3, "访": 4.9, "訪": 4.5, "拜访": 3.8, "探访": 3.7,
    "방문": 3.1, "زيارة": 2.8, "参观": 2.7, "来访": 2.5, "訪れ": 2.5,
    "游览": 2.0, "漫步": 1.4, "浏览": 1.4, "瀏覽": 1.7,
    "旅游": 1.55, "游客": 1.45,
    "旅遊": 1.1, "旅行": 0.85, "游": 0.95, "遊": 0.95, "景区": 0.7,
    "看": 0.37, "看看": 0.95, "查看": 0.63, "去看": 0.7,
    "臨": 1.1, "临": 1.1, "問": 1.0, "问": 1.0,
    "采访": 1.1, "记者": 0.95, "检查": 0.7,
}


def surface(token):
    return token.lstrip(" \t\r\n_./-([{")


def lexical_value(token):
    raw = surface(token)
    word = raw.lower()
    spaced = token[:1].isspace()
    if word == "visit":
        return 6.8 if spaced else (4.5 if token.startswith(".") else 5.8)
    if word in {"revisit", "revisited", "revisiting"}:
        return 5.2
    if word in {"visits", "visiting", "visited"}:
        return {"visits": 6.0, "visiting": 5.8, "visited": 5.2}[word]
    if word == "visitor":
        return 4.5 if spaced else 3.8
    if word == "visitors":
        return 4.0
    if word in {"visita", "visite", "visitar"}:
        return 3.8
    if word == "vis":
        return 3.45 if token.startswith(" V") else (2.9 if raw == "Vis" else 2.35)
    if word == "revis":
        return 3.5
    if word in VISITING:
        return VISITING[word]
    if word in {"access", "accesses", "accessed", "accessing"}:
        return 2.2 if spaced else 1.8
    if word == "アクセス":
        return 2.3
    if word in {"accessible", "accessibility", "accessor", "inaccessible"}:
        return 0.95
    if word in {"acess", "acesso"}:
        return 1.2
    if word == "acceso":
        return 0.65
    if word in {"check", "checks", "checked", "checking"}:
        return 0.8 if spaced else 0.7
    if word in {"see", "sees", "seeing"}:
        return 0.25 if spaced else 0.35
    if word in {"visible", "visibility", "vision", "visions", "isvisible",
                "setvisible", "setvisibility"}:
        return 0.9
    if word in {"visual", "visuals", "visually", "visualize", "visualization",
                "viewing", "inspect", "inspection", "inspections", "inspected",
                "examine", "examined", "examining"}:
        return 0.6
    if word in {"trip", "trips", "tour", "tours", "touring", "tourism"}:
        return 0.85
    if word in {"travel", "travels", "traveling", "travelling", "traveled",
                "travelled", "traveler", "traveller", "travelers", "tourist", "tourists",
                "voyage", "expedition", "traverse", "travers"}:
        return 0.55
    if word in {"walk", "walks", "walked", "walking", "explore", "exploring",
                "guest", "guests", "browse", "browsing"}:
        return 0.65
    if word in {"session", "sessions", "mission", "missions", "consult",
                "consultation", "consulting", "traffic"}:
        return 0.75
    if word in {"talk", "talks", "talking", "interview", "interact"}:
        return 0.35
    if word in {"revision", "revisions"}:
        return 1.5
    if word in {"revise", "revised", "modify", "modified", "modifications", "修改"}:
        return 0.7
    if word in {"visa", "visibly", "visc", "viscosity", "visceral"}:
        return 0.8
    if word == "website":
        return 0.23
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = surface(token).lower()
    # A new document has no preceding word or phrase context.
    if carry is None or carry[0] != doc:
        prev, strength, capital = "", 0.0, False
    else:
        _, prev, strength, capital = carry
    lexical = lexical_value(token)
    value = lexical
    # Recognize a visit-word split across two tokens.
    if prev in {"vis", "revis"} and not token[:1].isspace():
        if word in {"it", "its", "ited", "iting", "itor", "itors"}:
            value = 6.1 if word == "ited" else 5.0
            if word == "iting":
                value = 5.8 + (1.8 if capital and prev == "vis" else 0.0)
        elif word in {"iter", "itar", "iteur", "itez", "ita"}:
            value = 3.3
        elif word == "itation":
            value = 1.7
        elif word in {"ible", "ibly", "ibility", "ibilities", "ually", "ual", "ing"}:
            value = 1.1
    if not token[:1].isspace():
        if prev == "visit" and word in {"ar", "ando", "ante", "antes"}:
            value = 2.4
        elif prev in {"visual", "visualis", "visualiz"} and word in {
                "ise", "ised", "ized", "ize", "izing", "ization"}:
            value = 1.1
        elif prev == "訪" and word == "問":
            value = 4.0
    # Local phrases: go to, look at, visit the, access to, and so on.
    if token.startswith(" "):
        if word == "to":
            value += 0.45 * strength
            if prev in {"go", "goes", "went", "gone"}:
                value += 0.95
            elif prev == "going":
                value += 0.72
            elif prev in {"return", "returns", "returned", "returning", "back",
                          "come", "came", "comes", "coming"}:
                value += 0.55
            elif prev in {"trip", "trips", "navigate"}:
                value += 1.0
        elif word == "at" and prev in {"look", "looks", "looked", "looking",
                                      "glance", "glanced"}:
            value += 0.85
        elif word in {"the", "your"}:
            value += min(1.3, 0.4 * strength)
        elif word in {"this", "a", "an", "our", "my", "their", "his", "her", "its"}:
            value += min(0.6, 0.12 * strength)
        elif word == "of":
            if prev in {"tour", "tours", "revision", "revisions"}:
                value += 1.0
            elif strength >= 2.0:
                value += 0.45 * strength
    return (doc, word, lexical, surface(token)[:1].isupper()), float(value)

programs.haiku:
"""Visit-and-travel detector.

The component reads the current word (the token plus any fragments before it). It is
strongest on 'visit' and its relatives (visit, visiting, visitor, the 'vis' stem),
moderate on 'access', 'check' and travel words (trip, tour, travel), and it also fires
on the word 'to' when it follows a motion or access word (going to, go to, back to,
access to, a trip to). Everything else is near zero."""

READS = ()

MOTION_TO = ("go", "going", "goes", "went", "access", "trip", "visit", "pilgrimage")
RETURN_TO = ("back", "return", "returned", "returning")


def current_word(strings):
    """The word the newest token ends: its pieces, read back to the last space."""
    parts = []
    for s in reversed(strings):
        parts.append(s)
        if s[:1].isspace() or not s.strip().isalpha():
            break
    return "".join(reversed(parts)).strip().lower()


def step(carry, prefix, upstream):
    word = current_word(prefix.token_strings)
    before = current_word(prefix.token_strings[:-1])
    if word.startswith("visitor"):
        value = 4.5
    elif "visit" in word:
        value = 6.5
    elif word in ("vis", "revis", "-vis"):
        value = 3.5
    elif word.startswith("vis") and word != "visa":
        value = 1.0
    elif word == "access":
        value = 2.3
    elif "access" in word:
        value = 0.9
    elif "check" in word:
        value = 0.8
    elif any(k in word for k in ("trip", "tour", "travel")):
        value = 0.8
    elif word == "to" and before in MOTION_TO:
        value = 0.9
    elif word == "to" and before in RETURN_TO:
        value = 0.5
    else:
        value = 0.0
    return None, value

programs.luna:
"""Estimate a small feature for visiting, looking, and checking.

The component fires most strongly on forms of 'visit', and more mildly on
words about seeing or inspecting. It also gives a small positive response to
'to', which often accompanies these actions. This lexical sketch cannot
resolve all context-dependent activations.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if "visit" in word or word in {"vis", "visib"}:
        value = 5.0
    elif "check" in word:
        value = 0.75
    elif any(part in word for part in ("visual", "inspect", "see")):
        value = 0.5
    elif any(part in word for part in ("travel", "travell", "trip", "tour")):
        value = 0.45
    elif word == "to":
        value = 0.3
    else:
        value = 0.0
    return carry, value

programs.haiku:
READS = ()

WHOLE_WORDS = frozenset({
    "from", "room", "some", "come", "command", "common", "become", "custom",
    "random", "bottom", "zoom", "whom", "moment", "compute", "community",
    "company", "coming", "comment", "income", "something", "someone",
    "sometimes", "somewhat", "outcome", "compare", "component", "complete",
    "welcome", "bedroom", "mushroom", "bathroom", "wisdom", "kingdom",
    "freedom", "seldom", "symptom",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip(".(/_-\"'")
    word_start = token[:1] == " "
    i = word.find("om")
    before = word[i - 1] if i > 0 else ""
    if word in WHOLE_WORDS:
        value = 0.0
    elif word == "com":
        value = -0.7
    elif word == "atom" or (word.endswith(("om", "ом")) and len(word) <= 3):
        value = -4.0 if word.isascii() else -2.5
    elif word.startswith(("om", "ом")):
        value = -1.5
    elif before in ("c", "s", "w", "f", "r") and word.isascii():
        value = 0.0
    elif "om" in word or "ом" in word:
        value = -0.5 if word_start else -1.0
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Flag Latin or Cyrillic word pieces containing the letter pair om."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold().strip()
    if "ом" in token:
        return None, -0.54
    if "om" in token:
        # The pair alone in a short piece tends to produce a stronger response.
        return None, -1.58 if len(token) <= 3 else -0.54
    return None, 0.0

"""Weakly mark a few numerical and equation-writing patterns.

This conservative rule focuses on commas following a multi-digit number,
plus square-root and exponent notation, rather than marking punctuation
indiscriminately.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].rstrip()
    if not token:
        return None, 0.0

    if token.endswith(","):
        nearby = "".join(prefix.token_strings[max(0, len(prefix) - 6):-1])
        digits = 0
        for char in reversed(nearby):
            if char.isdigit():
                digits += 1
            elif char in " .,$+-×^()":
                continue
            else:
                break
        if digits >= 2:
            return None, 0.26 * 0.65

    lower = token.lower()
    if "sqrt" in lower:
        return None, 0.26 * 0.7
    if token.endswith(("^", ")^", "=")):
        return None, 0.26 * 0.4
    return None, 0.0

