programs.luna:
"""Predict a small bump for public-service, national, fire, and shell terms."""

READS = ()

PUBLIC_SERVICE = {
    "staff", "military", "troop", "troops", "police", "officer",
    "officers", "soldier", "soldiers", "personnel", "authority",
    "authorities", "official", "officials", "army", "navy", "airforce",
    "battalion", "regiment", "firefighter", "firefighters",
}
NATIONALITIES = {
    "american", "british", "canadian", "chinese", "dutch", "english",
    "finnish", "french", "german", "indian", "irish", "israeli",
    "italian", "japanese", "korean", "mexican", "norwegian", "polish",
    "russian", "scottish", "spanish", "swedish", "welsh",
}
FIRE_TERMS = {"fire", "flame", "flames"}
SHELL_TERMS = {"bash", "shell"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_doc, previous_word = carry or (doc, "")
    if doc != previous_doc or any(ch.isspace() for ch in token):
        word = token.strip()
    else:
        word = previous_word + token
    word = word.strip(" \t\n.,;:!?()[]{}\"'`“”‘’")
    lower = word.casefold()
    active = (
        lower in PUBLIC_SERVICE
        or lower in NATIONALITIES
        or lower in FIRE_TERMS
        or lower in SHELL_TERMS
    )
    return (doc, word), 1.0 if active else 0.0
